functions.showAiModelDiscovery:
function showAiModelDiscovery() {
  var eli = window.eli;
  var existing = document.getElementById("_af_models_overlay");
  if (existing && existing.parentNode) existing.parentNode.removeChild(existing);

  var ov = document.createElement("div");
  ov.id = "_af_models_overlay";
  ov.style.cssText =
    "position:fixed;inset:0;z-index:99999;background:rgba(15,23,42,0.55);" +
    "display:flex;align-items:center;justify-content:center;padding:20px;" +
    "font-family:Inter,'Segoe UI',system-ui,sans-serif;";

  ov.innerHTML =
    '<div style="background:#fff;width:min(720px,96vw);max-height:92vh;display:flex;flex-direction:column;border:1px solid #cbd5e1;box-shadow:0 24px 60px rgba(15,23,42,0.45);">' +
      '<div style="padding:14px 18px;background:linear-gradient(135deg,#0d1b2a,#1b263b);color:#fff;display:flex;justify-content:space-between;align-items:center;">' +
        '<div>' +
          '<div style="font:800 11px/1 Inter,sans-serif;letter-spacing:0.12em;text-transform:uppercase;color:#c9a227;">Admin Fleet · AI</div>' +
          '<div style="font:800 17px/1.2 Inter,sans-serif;margin-top:2px;">Discover AI Models</div>' +
        '</div>' +
        '<button id="_af_models_close" type="button" aria-label="Close" style="background:transparent;color:#fff;border:1px solid #475569;width:28px;height:28px;cursor:pointer;font:700 14px/1 Inter,sans-serif;">×</button>' +
      '</div>' +
      '<div id="_af_models_body" style="padding:14px 16px;overflow-y:auto;flex:1;background:#f8fafc;">' +
        '<div id="_af_models_status" style="font:600 12px/1.4 Inter,sans-serif;color:#64748b;padding:24px 0;text-align:center;">' +
          '⏳ Decrypting API key…' +
        '</div>' +
      '</div>' +
      '<div id="_af_models_footer" style="padding:10px 16px;border-top:1px solid #e2e8f0;background:#fff;display:flex;justify-content:space-between;align-items:center;gap:10px;font:500 11px/1.3 Inter,sans-serif;">' +
        '<div id="_af_models_selcount" style="color:#64748b;">—</div>' +
        '<div style="display:flex;gap:6px;align-items:center;">' +
          '<label style="display:flex;align-items:center;gap:4px;color:#475569;cursor:pointer;">' +
            '<input type="radio" name="_af_save_mode" value="replace" checked> Replace' +
          '</label>' +
          '<label style="display:flex;align-items:center;gap:4px;color:#475569;cursor:pointer;">' +
            '<input type="radio" name="_af_save_mode" value="append"> Append' +
          '</label>' +
          '<button id="_af_models_save" type="button" disabled style="font:700 11px/1 Inter,sans-serif;padding:8px 14px;background:#1565c0;color:#fff;border:none;cursor:pointer;opacity:0.5;">💾 Save to ai_model_list</button>' +
        '</div>' +
      '</div>' +
    '</div>';

  document.body.appendChild(ov);
  function _close() { if (ov.parentNode) ov.parentNode.removeChild(ov); }
  ov.querySelector("#_af_models_close").onclick = _close;
  ov.onclick = function (e) { if (e.target === ov) _close(); };

  var statusEl = ov.querySelector("#_af_models_status");
  var bodyEl = ov.querySelector("#_af_models_body");
  var selCountEl = ov.querySelector("#_af_models_selcount");
  var saveBtn = ov.querySelector("#_af_models_save");

  function _esc(s) {
    return String(s == null ? "" : s).replace(/[&<>"']/g, function (c) {
      return { "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c];
    });
  }
  function _setStatus(msg, isErr) {
    statusEl.style.display = "block";
    statusEl.style.color = isErr ? "#b91c1c" : "#64748b";
    statusEl.innerHTML = msg;
  }
  function _renderModels(models, currentList) {
    statusEl.style.display = "none";
    var currentSet = {};
    (currentList || []).forEach(function (m) { currentSet[m] = true; });
    var html = '<div style="font:600 11px/1.4 Inter,sans-serif;color:#475569;margin-bottom:10px;">' +
      'Found <b>' + models.length + '</b> model' + (models.length === 1 ? '' : 's') +
      ' your API key can access. ' +
      'Image-capable models marked 🖼. Currently in <code>ai_model_list</code>: <b>' +
      (currentList || []).length + '</b>.' +
      '</div>';
    html += '<div style="display:flex;gap:6px;margin-bottom:10px;">' +
      '<button id="_af_models_selall" type="button" style="font:700 10px/1 Inter,sans-serif;padding:6px 10px;background:#fff;border:1px solid #cbd5e1;cursor:pointer;">☑ Select all</button>' +
      '<button id="_af_models_selnone" type="button" style="font:700 10px/1 Inter,sans-serif;padding:6px 10px;background:#fff;border:1px solid #cbd5e1;cursor:pointer;">☐ Clear all</button>' +
      '<button id="_af_models_selimg" type="button" style="font:700 10px/1 Inter,sans-serif;padding:6px 10px;background:#dcfce7;border:1px solid #86efac;color:#15803d;cursor:pointer;">🖼 Select image-capable</button>' +
      '<button id="_af_models_selcur" type="button" style="font:700 10px/1 Inter,sans-serif;padding:6px 10px;background:#fef3c7;border:1px solid #fde68a;color:#92400e;cursor:pointer;">↻ Select currently-in-list</button>' +
      '</div>';
    html += '<div id="_af_models_list" style="background:#fff;border:1px solid #e2e8f0;">';
    models.forEach(function (m, i) {
      var shortName = String(m.name).replace(/^models\//, "");
      var isImage = /image/i.test(m.name) || (m.description && /image/i.test(m.description));
      var isCurrent = !!currentSet[shortName];
      var methods = (m.supportedGenerationMethods || []).join(", ");
      html += '<label data-mod-row="' + i + '" data-name="' + _esc(shortName) +
        '" data-isimage="' + (isImage ? "1" : "0") +
        '" data-iscur="' + (isCurrent ? "1" : "0") +
        '" style="display:flex;gap:10px;padding:10px 14px;border-bottom:1px solid #f1f5f9;cursor:pointer;">' +
        '<input type="checkbox" class="_af_models_chk"' + (isCurrent ? ' checked' : '') +
          ' style="flex-shrink:0;margin-top:3px;">' +
        '<div style="flex:1;min-width:0;">' +
          '<div style="font:700 12px/1.3 Inter,sans-serif;color:#0f172a;">' +
            _esc(shortName) +
            (isImage ? ' <span style="font:700 9px/1 Inter,sans-serif;padding:2px 5px;background:#dcfce7;color:#15803d;border:1px solid #86efac;letter-spacing:0.4px;">🖼 IMAGE</span>' : '') +
            (isCurrent ? ' <span style="font:700 9px/1 Inter,sans-serif;padding:2px 5px;background:#fef3c7;color:#92400e;border:1px solid #fde68a;letter-spacing:0.4px;">IN LIST</span>' : '') +
          '</div>' +
          (m.displayName ? '<div style="font:500 11px/1.4 Inter,sans-serif;color:#475569;margin-top:2px;">' + _esc(m.displayName) + '</div>' : '') +
          (m.description ? '<div style="font:500 10.5px/1.5 Inter,sans-serif;color:#64748b;margin-top:3px;max-height:48px;overflow:hidden;">' + _esc(m.description.slice(0, 280)) + (m.description.length > 280 ? '…' : '') + '</div>' : '') +
          '<div style="font:500 9.5px/1.4 Inter,sans-serif;color:#94a3b8;margin-top:4px;font-family:ui-monospace,Consolas,monospace;">methods: ' + _esc(methods) + '</div>' +
        '</div>' +
      '</label>';
    });
    html += '</div>';
    bodyEl.innerHTML = html;

    function _selected() {
      return Array.prototype.slice.call(bodyEl.querySelectorAll('._af_models_chk:checked'))
        .map(function (cb) { return cb.parentNode.getAttribute("data-name"); });
    }
    function _updateCount() {
      var n = bodyEl.querySelectorAll('._af_models_chk:checked').length;
      selCountEl.textContent = n + " selected";
      saveBtn.disabled = n === 0;
      saveBtn.style.opacity = n === 0 ? "0.5" : "1";
    }
    function _setAll(predicate) {
      bodyEl.querySelectorAll("label[data-mod-row]").forEach(function (row) {
        var cb = row.querySelector("._af_models_chk");
        if (cb) cb.checked = predicate ? !!predicate(row) : true;
      });
      _updateCount();
    }
    bodyEl.querySelectorAll("._af_models_chk").forEach(function (cb) {
      cb.addEventListener("change", _updateCount);
    });
    bodyEl.querySelector("#_af_models_selall").onclick = function () { _setAll(function () { return true; }); };
    bodyEl.querySelector("#_af_models_selnone").onclick = function () { _setAll(function () { return false; }); };
    bodyEl.querySelector("#_af_models_selimg").onclick = function () {
      _setAll(function (row) { return row.getAttribute("data-isimage") === "1"; });
    };
    bodyEl.querySelector("#_af_models_selcur").onclick = function () {
      _setAll(function (row) { return row.getAttribute("data-iscur") === "1"; });
    };
    _updateCount();

    saveBtn.onclick = function () {
      var picked = _selected();
      if (!picked.length) return;
      var mode = ov.querySelector('input[name="_af_save_mode"]:checked').value;
      var finalList = picked;
      if (mode === "append") {
        var merged = (currentList || []).slice();
        picked.forEach(function (p) { if (merged.indexOf(p) === -1) merged.push(p); });
        finalList = merged;
      }
      try {
        var ok = eli.settings.set("ai_model_list", finalList, { layer: "user" });
        if (!ok) throw new Error("eli.settings.set returned false");
        if (window.showToast) window.showToast("✅ Saved " + finalList.length + " models to ai_model_list", "ok");
        _close();
      } catch (err) {
        if (window.showToast) window.showToast("⚠️ Save failed: " + (err && err.message || "unknown"), "err");
      }
    };
  }

  // ─── Decrypt + fetch ──────────────────────────────────────────────
  // Bundler scope: each top-level fn is eval'd in isolation via new
  // Function(), so cross-function calls MUST go through window.* (bare
  // names don't resolve). See CLAUDE.md "bundler scope" notes.
  window._decryptApiKey().then(function (apiKey) {
    if (!apiKey) {
      _setStatus("⚠️ No API key found. Set one in Settings first.", true);
      return;
    }
    _setStatus("⏳ Calling Gemini ListModels…");
    return window._fetchModels(apiKey).then(function (models) {
      if (!models || !models.length) {
        _setStatus("⚠️ No models returned. Your API key may not have access.", true);
        return;
      }
      // Filter to models that support generateContent (others can't be called
      // by our complete/generateImage path).
      var usable = models.filter(function (m) {
        return (m.supportedGenerationMethods || []).indexOf("generateContent") !== -1;
      });
      // Sort: image-capable first, then alphabetical.
      var isImage = function (m) { return /image/i.test(m.name) || (m.description && /image/i.test(m.description)); };
      usable.sort(function (a, b) {
        var ai = isImage(a) ? 0 : 1;
        var bi = isImage(b) ? 0 : 1;
        if (ai !== bi) return ai - bi;
        return String(a.name).localeCompare(String(b.name));
      });
      var currentList = [];
      try { currentList = eli.settings.get("ai_model_list") || []; } catch (_) {}
      _renderModels(usable, currentList);
    });
  }).catch(function (err) {
    _setStatus("⚠️ " + (err && err.message || "Discovery failed"), true);
  });
}

// ─── Helpers (top-level for bundle export) ────────────────────────────

// Decrypts the API key from localStorage. Mirrors the kernel's
// loadApiKey() path. Uses window._eliDecryptFromRepo + window.ELI_BUNDLE_CIPHER
// when the blob is encrypted; falls back to plaintext .k field when not.
// Returns Promise<string|null>.

functions._decryptApiKey:
function _decryptApiKey() {
  return new Promise(function (resolve) {
    try {
      var stored = window.eli.compat.lsGet("eli_gemini_api_key");
      if (!stored) { resolve(null); return; }
      var blob;
      try { blob = JSON.parse(stored); }
      catch (e) { resolve(null); return; }
      // Encrypted path — use kernel's helpers if available.
      if (typeof window._eliDecryptFromRepo === "function" &&
          typeof window._eliIsEncryptedBlob === "function" &&
          window._eliIsEncryptedBlob(blob)) {
        var cipher = window.ELI_BUNDLE_CIPHER || "ELI_COLGATE_DATA";
        window._eliDecryptFromRepo(cipher, blob)
          .then(function (inner) {
            if (inner && inner.k) resolve(String(inner.k));
            else resolve(null);
          })
          .catch(function () { resolve(null); });
      } else if (blob && blob.k) {
        // Plaintext (legacy/dev path).
        resolve(String(blob.k));
      } else {
        resolve(null);
      }
    } catch (e) {
      resolve(null);
    }
  });
}

// Calls the Gemini ListModels endpoint. Returns Promise<Array<Model>>.
// Throws if the response has an error field.

functions._fetchModels:
function _fetchModels(apiKey) {
  var url = "https://generativelanguage.googleapis.com/v1beta/models?key=" +
    encodeURIComponent(apiKey) + "&pageSize=200";
  return fetch(url).then(function (resp) {
    return resp.json().then(function (json) {
      if (json.error) throw new Error(json.error.message || "API error");
      return json.models || [];
    });
  });
}

// Note: do NOT add a trailing `window.X = X` here. The bundler eval
// loop (taskpane_v3.js:6421) auto-attaches every top-level function
// declaration to window. A trailing statement triggers the "trailing-
// statement bug" called out in CLAUDE.md (breaks the prior function's
// eval). The functions in this file (showAiModelDiscovery,
// _decryptApiKey, _fetchModels) are already on window via that path.

functions.showAiModelsManager:
function showAiModelsManager() {
  var eli = window.eli;
  var STORE = "config";
  var DRAFT_ID = "_admin_ai_models_draft";

  var existing = document.getElementById("_af_models_overlay");
  if (existing && existing.parentNode) existing.parentNode.removeChild(existing);

  var ov = document.createElement("div");
  ov.id = "_af_models_overlay";
  ov.style.cssText =
    "position:fixed;inset:0;z-index:99999;background:rgba(15,23,42,0.55);" +
    "display:flex;align-items:center;justify-content:center;padding:20px;" +
    "font-family:Inter,'Segoe UI',system-ui,sans-serif;";

  ov.innerHTML =
    '<div style="background:#fff;width:min(820px,96vw);max-height:92vh;display:flex;flex-direction:column;border:1px solid #cbd5e1;box-shadow:0 24px 60px rgba(15,23,42,0.45);">' +
      '<div style="padding:14px 18px;background:linear-gradient(135deg,#0d1b2a,#1b263b);color:#fff;display:flex;justify-content:space-between;align-items:center;">' +
        '<div>' +
          '<div style="font:800 11px/1 Inter,sans-serif;letter-spacing:0.12em;text-transform:uppercase;color:#c9a227;">Admin Fleet · AI</div>' +
          '<div style="font:800 17px/1.2 Inter,sans-serif;margin-top:2px;">AI Models Manager</div>' +
        '</div>' +
        '<button id="_af_amm_close" type="button" aria-label="Close" style="background:transparent;color:#fff;border:1px solid #475569;width:28px;height:28px;cursor:pointer;font:700 14px/1 Inter,sans-serif;">×</button>' +
      '</div>' +
      '<div id="_af_amm_body" style="padding:14px 16px;overflow-y:auto;flex:1;background:#f8fafc;font:500 12px/1.5 Inter,sans-serif;color:#1e293b;">' +
        '<div style="text-align:center;padding:24px 0;color:#64748b;">⏳ Loading…</div>' +
      '</div>' +
    '</div>';

  document.body.appendChild(ov);
  function _close() { if (ov.parentNode) ov.parentNode.removeChild(ov); }
  ov.querySelector("#_af_amm_close").onclick = _close;
  ov.onclick = function (e) { if (e.target === ov) _close(); };

  // ─── Load draft + render ──────────────────────────────────────────
  window._amLoadDraft().then(function (draft) {
    window._amRender(ov, draft);
  });
}

// ─── IDB helpers ──────────────────────────────────────────────────────

functions._amLoadDraft:
function _amLoadDraft() {
  var eli = window.eli;
  return eli.storage.get("config", "_admin_ai_models_draft").then(function (row) {
    if (row) return row;
    // First-time: seed from current eli.settings + register ai_image_model.
    var list = [];
    var textModel = "";
    var imageModel = "";
    try { list = eli.settings.get("ai_model_list") || []; } catch (_) {}
    try { textModel = eli.settings.get("ai_model") || ""; } catch (_) {}
    try { imageModel = eli.settings.get("ai_image_model") || ""; } catch (_) {}
    return {
      id: "_admin_ai_models_draft",
      list: list.slice(),
      textModel: textModel,
      imageModel: imageModel,
      updatedAt: new Date().toISOString(),
      lastPushedAt: null,
      lastPushedMode: null,
    };
  });
}

functions._amSaveDraft:
function _amSaveDraft(draft) {
  draft.updatedAt = new Date().toISOString();
  return window.eli.storage.put("config", draft);
}

// ─── Render ───────────────────────────────────────────────────────────

functions._amRender:
function _amRender(ov, draft) {
  var eli = window.eli;
  var body = ov.querySelector("#_af_amm_body");

  function _esc(s) {
    return String(s == null ? "" : s).replace(/[&<>"']/g, function (c) {
      return { "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c];
    });
  }
  function _isImage(name) { return /image/i.test(String(name || "")); }

  var activeText = "";
  var activeImage = "";
  try { activeText = eli.settings.get("ai_model") || ""; } catch (_) {}
  try { activeImage = eli.settings.get("ai_image_model") || ""; } catch (_) {}

  // Check admin-override status for each setting (informational only).
  var textForced = false;
  var imageForced = false;
  try { textForced = eli.settings.isAdminOverridden && eli.settings.isAdminOverridden("ai_model", "force"); } catch (_) {}
  try { imageForced = eli.settings.isAdminOverridden && eli.settings.isAdminOverridden("ai_image_model", "force"); } catch (_) {}

  var listHtml = "";
  if (!draft.list.length) {
    listHtml = '<div style="padding:14px;color:#94a3b8;text-align:center;font-style:italic;">No models yet — click Discover or Add manually.</div>';
  } else {
    listHtml = draft.list.map(function (name, i) {
      var img = _isImage(name);
      return '<div data-am-row="' + i + '" style="display:flex;align-items:center;gap:8px;padding:8px 12px;border-bottom:1px solid #f1f5f9;">' +
        '<code style="flex:1;font:600 11px/1.3 ui-monospace,Consolas,monospace;color:#0f172a;">' + _esc(name) + '</code>' +
        (img ? '<span style="font:700 9px/1 Inter,sans-serif;padding:2px 5px;background:#dcfce7;color:#15803d;border:1px solid #86efac;letter-spacing:0.3px;">🖼 IMAGE</span>' : '') +
        '<button data-am-remove="' + i + '" type="button" style="font:700 12px/1 Inter,sans-serif;padding:4px 8px;background:#fee2e2;border:1px solid #fecaca;color:#b91c1c;cursor:pointer;">×</button>' +
      '</div>';
    }).join("");
  }

  // Text picker — all models in list
  var textOpts = '<option value="">— none —</option>' + draft.list.map(function (n) {
    return '<option value="' + _esc(n) + '"' + (n === draft.textModel ? ' selected' : '') + '>' + _esc(n) + '</option>';
  }).join("");

  // Image picker — filter to /image/i name pattern
  var imageModels = draft.list.filter(_isImage);
  var imageOpts;
  if (!imageModels.length) {
    imageOpts = '<option value="">— no image models in list —</option>';
  } else {
    imageOpts = '<option value="">— none (disabled) —</option>' + imageModels.map(function (n) {
      return '<option value="' + _esc(n) + '"' + (n === draft.imageModel ? ' selected' : '') + '>' + _esc(n) + '</option>';
    }).join("");
  }

  body.innerHTML =
    // ─── Section 1: Available Models ──────────────────────────────
    '<div style="background:#fff;border:1px solid #e2e8f0;margin-bottom:14px;">' +
      '<div style="padding:10px 14px;background:#f1f5f9;border-bottom:1px solid #e2e8f0;display:flex;justify-content:space-between;align-items:center;">' +
        '<div style="font:800 11px/1 Inter,sans-serif;letter-spacing:0.5px;text-transform:uppercase;color:#1e293b;">📚 Available models (' + draft.list.length + ')</div>' +
        '<div style="display:flex;gap:6px;">' +
          '<button id="_am_discover" type="button" style="font:700 10px/1 Inter,sans-serif;letter-spacing:0.4px;text-transform:uppercase;padding:6px 10px;background:linear-gradient(180deg,#fef3c7,#fde68a);border:1px solid #d97706;color:#78350f;cursor:pointer;">🔍 Discover</button>' +
        '</div>' +
      '</div>' +
      '<div id="_am_list" style="max-height:200px;overflow-y:auto;">' + listHtml + '</div>' +
      '<div style="padding:10px 14px;border-top:1px solid #f1f5f9;display:flex;gap:6px;align-items:center;">' +
        '<input id="_am_add" type="text" placeholder="model name (e.g. gemini-3.1-pro)" style="flex:1;padding:6px 8px;font:500 11px ui-monospace,Consolas,monospace;border:1px solid #cbd5e1;">' +
        '<button id="_am_add_btn" type="button" style="font:700 10px/1 Inter,sans-serif;letter-spacing:0.3px;text-transform:uppercase;padding:6px 10px;background:#fff;border:1px solid #cbd5e1;color:#1e293b;cursor:pointer;">+ Add</button>' +
      '</div>' +
    '</div>' +

    // ─── Section 2: Active Text Model ──────────────────────────────
    '<div style="background:#fff;border:1px solid #e2e8f0;margin-bottom:14px;padding:12px 14px;">' +
      '<div style="font:800 11px/1 Inter,sans-serif;letter-spacing:0.5px;text-transform:uppercase;color:#1e293b;margin-bottom:6px;">🤖 Active text/completion model</div>' +
      '<div style="font:500 11px/1.4 Inter,sans-serif;color:#64748b;margin-bottom:8px;">Active locally: <code style="color:#0f172a;">' + _esc(activeText || "(not set)") + '</code>' + (textForced ? ' · <span style="color:#92400e;">🔒 force-pushed</span>' : '') + '</div>' +
      '<select id="_am_text_picker" style="width:100%;padding:7px 9px;font:600 12px ui-monospace,Consolas,monospace;border:1px solid #1565c0;background:#fff;">' + textOpts + '</select>' +
    '</div>' +

    // ─── Section 3: Active Image Model ─────────────────────────────
    '<div style="background:#fff;border:1px solid #e2e8f0;margin-bottom:14px;padding:12px 14px;">' +
      '<div style="font:800 11px/1 Inter,sans-serif;letter-spacing:0.5px;text-transform:uppercase;color:#1e293b;margin-bottom:6px;">🖼 Active image generation model</div>' +
      '<div style="font:500 11px/1.4 Inter,sans-serif;color:#64748b;margin-bottom:8px;">Active locally: <code style="color:#0f172a;">' + _esc(activeImage || "(not set)") + '</code>' + (imageForced ? ' · <span style="color:#92400e;">🔒 force-pushed</span>' : '') + '</div>' +
      '<select id="_am_image_picker"' + (imageModels.length ? '' : ' disabled') + ' style="width:100%;padding:7px 9px;font:600 12px ui-monospace,Consolas,monospace;border:1px solid ' + (imageModels.length ? '#15803d' : '#cbd5e1') + ';background:#fff;' + (imageModels.length ? '' : 'opacity:0.5;') + '">' + imageOpts + '</select>' +
      (imageModels.length ? '' : '<div style="font:500 10px/1.4 Inter,sans-serif;color:#92400e;margin-top:6px;">Add an image-capable model (anything with "image" in the name) to the list above first.</div>') +
    '</div>' +

    // ─── Section 4: Apply + Push instructions ──────────────────────
    '<div style="background:#fff;border:1px solid #e2e8f0;padding:12px 14px;display:flex;justify-content:space-between;align-items:center;gap:10px;">' +
      '<div style="font:500 10.5px/1.4 Inter,sans-serif;color:#64748b;flex:1;">' +
        'Apply writes all three (list + text + image) to your local settings. ' +
        'To push to colleagues, scroll to a user row → expand Settings → click 📤 Push on the desired key.' +
      '</div>' +
      '<button id="_am_apply" type="button" style="flex-shrink:0;font:800 11px/1 Inter,sans-serif;letter-spacing:0.5px;text-transform:uppercase;padding:10px 16px;background:#1565c0;color:#fff;border:none;cursor:pointer;">✅ Apply to me</button>' +
    '</div>';

  // ─── Wire handlers ─────────────────────────────────────────────────
  body.querySelector("#_am_discover").onclick = function () {
    // Reuse the existing discovery flow inline. Returns picked models;
    // we APPEND to our draft list (deduped) and re-render.
    window._amRunDiscovery(ov).then(function (picked) {
      if (!picked || !picked.length) return;
      picked.forEach(function (name) {
        if (draft.list.indexOf(name) === -1) draft.list.push(name);
      });
      window._amSaveDraft(draft).then(function () { window._amRender(ov, draft); });
    });
  };

  body.querySelector("#_am_add_btn").onclick = function () {
    var inp = body.querySelector("#_am_add");
    var v = (inp.value || "").trim();
    if (!v) return;
    if (draft.list.indexOf(v) !== -1) {
      if (window.showToast) window.showToast("Already in list", "warn");
      return;
    }
    draft.list.push(v);
    window._amSaveDraft(draft).then(function () { window._amRender(ov, draft); });
  };

  body.querySelectorAll("button[data-am-remove]").forEach(function (btn) {
    btn.onclick = function () {
      var i = parseInt(btn.getAttribute("data-am-remove"), 10);
      var removed = draft.list[i];
      draft.list.splice(i, 1);
      // If the removed entry was the active text/image, clear it.
      if (draft.textModel === removed) draft.textModel = "";
      if (draft.imageModel === removed) draft.imageModel = "";
      window._amSaveDraft(draft).then(function () { window._amRender(ov, draft); });
    };
  });

  body.querySelector("#_am_text_picker").onchange = function () {
    draft.textModel = this.value;
    window._amSaveDraft(draft);
  };

  var imgPicker = body.querySelector("#_am_image_picker");
  if (imgPicker) {
    imgPicker.onchange = function () {
      draft.imageModel = this.value;
      window._amSaveDraft(draft);
    };
  }

  body.querySelector("#_am_apply").onclick = function () {
    var ok = true;
    try { ok = ok && eli.settings.set("ai_model_list", draft.list.slice(), { layer: "user" }); } catch (e) { ok = false; }
    if (draft.textModel) {
      try { ok = ok && eli.settings.set("ai_model", draft.textModel, { layer: "user" }); } catch (e) { ok = false; }
    }
    if (draft.imageModel) {
      try { ok = ok && eli.settings.set("ai_image_model", draft.imageModel, { layer: "user" }); } catch (e) { ok = false; }
    }
    if (ok) {
      if (window.showToast) window.showToast("✅ Applied to your local settings", "ok");
      window._amRender(ov, draft); // refresh status display
    } else {
      if (window.showToast) window.showToast("⚠️ Some applies failed — check console", "warn");
    }
  };
}

// ─── Discovery sub-flow ───────────────────────────────────────────────
// Reuses _decryptApiKey + _fetchModels from showAiModelDiscovery.js.
// Returns a Promise that resolves to an array of picked model name strings
// (or [] if user cancels). Renders a sub-dialog over the manager.

functions._amRunDiscovery:
function _amRunDiscovery(parentOv) {
  return new Promise(function (resolve) {
    var sub = document.createElement("div");
    sub.style.cssText =
      "position:fixed;inset:0;z-index:100000;background:rgba(15,23,42,0.65);" +
      "display:flex;align-items:center;justify-content:center;padding:20px;" +
      "font-family:Inter,'Segoe UI',system-ui,sans-serif;";
    sub.innerHTML =
      '<div style="background:#fff;width:min(620px,96vw);max-height:88vh;display:flex;flex-direction:column;border:1px solid #cbd5e1;">' +
        '<div style="padding:12px 16px;background:linear-gradient(135deg,#7c3aed,#5b21b6);color:#fff;display:flex;justify-content:space-between;align-items:center;">' +
          '<div style="font:800 13px/1.2 Inter,sans-serif;">🔍 Discover models</div>' +
          '<button id="_amd_cancel" type="button" style="background:transparent;color:#fff;border:1px solid rgba(255,255,255,0.35);width:24px;height:24px;cursor:pointer;font:700 12px/1 Inter,sans-serif;">×</button>' +
        '</div>' +
        '<div id="_amd_status" style="padding:24px 16px;text-align:center;font:600 12px/1.4 Inter,sans-serif;color:#64748b;">⏳ Decrypting API key…</div>' +
        '<div id="_amd_body" style="overflow-y:auto;flex:1;background:#f8fafc;"></div>' +
        '<div id="_amd_footer" style="padding:10px 14px;border-top:1px solid #e2e8f0;display:none;justify-content:space-between;align-items:center;">' +
          '<div id="_amd_count" style="font:500 11px Inter,sans-serif;color:#64748b;">0 selected</div>' +
          '<button id="_amd_ok" type="button" disabled style="font:700 11px/1 Inter,sans-serif;letter-spacing:0.4px;text-transform:uppercase;padding:8px 14px;background:#7c3aed;color:#fff;border:none;cursor:pointer;opacity:0.5;">Add to list</button>' +
        '</div>' +
      '</div>';
    document.body.appendChild(sub);

    function _closeSub(picked) {
      if (sub.parentNode) sub.parentNode.removeChild(sub);
      resolve(picked || []);
    }
    sub.querySelector("#_amd_cancel").onclick = function () { _closeSub([]); };

    var status = sub.querySelector("#_amd_status");
    var bodyEl = sub.querySelector("#_amd_body");
    var footer = sub.querySelector("#_amd_footer");
    var countEl = sub.querySelector("#_amd_count");
    var okBtn = sub.querySelector("#_amd_ok");

    window._decryptApiKey().then(function (key) {
      if (!key) {
        status.textContent = "⚠️ No API key found. Set one in Settings first.";
        status.style.color = "#b91c1c";
        return;
      }
      status.textContent = "⏳ Calling Gemini ListModels…";
      return window._fetchModels(key).then(function (models) {
        if (!models || !models.length) {
          status.textContent = "⚠️ No models returned.";
          status.style.color = "#b91c1c";
          return;
        }
        var usable = models.filter(function (m) {
          return (m.supportedGenerationMethods || []).indexOf("generateContent") !== -1;
        });
        var isImg = function (m) { return /image/i.test(m.name); };
        usable.sort(function (a, b) {
          var ai = isImg(a) ? 0 : 1;
          var bi = isImg(b) ? 0 : 1;
          if (ai !== bi) return ai - bi;
          return String(a.name).localeCompare(String(b.name));
        });
        status.style.display = "none";
        footer.style.display = "flex";
        bodyEl.innerHTML = usable.map(function (m, i) {
          var shortName = String(m.name).replace(/^models\//, "");
          var img = isImg(m);
          return '<label data-amd-row="' + i + '" data-name="' + shortName.replace(/"/g, "&quot;") + '" style="display:flex;gap:8px;padding:8px 14px;border-bottom:1px solid #f1f5f9;cursor:pointer;">' +
            '<input type="checkbox" class="_amd_chk" style="margin-top:3px;">' +
            '<div style="flex:1;min-width:0;">' +
              '<div style="font:600 11px/1.3 ui-monospace,Consolas,monospace;color:#0f172a;">' + shortName.replace(/</g, "&lt;") + (img ? ' <span style="font:700 9px Inter,sans-serif;padding:1px 4px;background:#dcfce7;color:#15803d;border:1px solid #86efac;">🖼</span>' : '') + '</div>' +
              (m.displayName ? '<div style="font:500 10.5px/1.3 Inter,sans-serif;color:#475569;margin-top:2px;">' + String(m.displayName).replace(/</g, "&lt;") + '</div>' : '') +
            '</div>' +
          '</label>';
        }).join("");
        function _upd() {
          var n = bodyEl.querySelectorAll("._amd_chk:checked").length;
          countEl.textContent = n + " selected";
          okBtn.disabled = n === 0;
          okBtn.style.opacity = n === 0 ? "0.5" : "1";
        }
        bodyEl.querySelectorAll("._amd_chk").forEach(function (cb) {
          cb.addEventListener("change", _upd);
        });
        okBtn.onclick = function () {
          var picked = Array.prototype.slice.call(bodyEl.querySelectorAll("._amd_chk:checked"))
            .map(function (cb) { return cb.parentNode.getAttribute("data-name"); });
          _closeSub(picked);
        };
      });
    }).catch(function (err) {
      status.textContent = "⚠️ " + (err && err.message || "Discovery failed");
      status.style.color = "#b91c1c";
    });
  });
}

jsonTools.init:
function init(eli) {
  if (!eli || !eli.bus || !eli.storage || !eli.compat) return;
  var bundle = eli.tools && eli.tools._loaded && eli.tools._loaded.admin_fleet;
  if (!bundle) return;

  // 2026-05-25: ai_image_model setting registration moved to eli_settings
  // — every user has eli_settings, only admins have admin_fleet, so the
  // registration needs to live where every install picks it up. admin_fleet
  // still reads/writes via eli.settings.get/set.

  // ── Constants ─────────────────────────────────────────────────────
  var GH_OWNER  = "apndrewn";
  var GH_REPO   = "eli-data";
  var GH_BRANCH = "main";
  var IDENTITY_PATH  = "fleet-identity.enc.json";
  var OVERRIDES_PATH = "admin-overrides.json";
  var STORE_CONFIG = "config";
  var LOCAL_LOOKUP_CACHE_KEY = "_admin_fleet_lookup_cache";

  // ── State ─────────────────────────────────────────────────────────
  var _lookup = {};            // userId → { email, firstName, lastName, role, notes, ... }
  var _telemetryByUserId = {}; // userId → fleet block (most recent)
  var _telemetryRowsByUserKey = {}; // userKey → full digest (for legacy users not in lookup)
  var _adminOverrides = null;  // current admin-overrides.json contents
  var _adminOverridesSha = null;
  var _identitySha = null;
  var _lookupLoaded = false;
  var _toolsManifest = null;   // current tools-manifest-v3.json contents
  var _toolsManifestSha = null;
  var _pat = null;
  var _password = null;
  var _userIdentity = null;

  function _esc(s) {
    return String(s == null ? "" : s)
      .replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;")
      .replace(/"/g, "&quot;").replace(/'/g, "&#39;");
  }
  function _ago(ts) {
    if (!ts) return "—";
    var d = (typeof ts === "number") ? ts : new Date(ts).getTime();
    var delta = Date.now() - d;
    if (!isFinite(delta) || delta < 0) return "—";
    var min = Math.floor(delta / 60000);
    if (min < 1) return "just now";
    if (min < 60) return min + " min ago";
    var hr = Math.floor(min / 60);
    if (hr < 24) return hr + "h ago";
    var day = Math.floor(hr / 24);
    if (day < 30) return day + "d ago";
    return new Date(d).toLocaleDateString();
  }
  function _toast(msg, kind) {
    if (typeof showToast === "function") showToast(msg, kind || "info");
  }

  // 2026-05-23: derive the telemetry userKey from an identity record.
  // Mirrors eli_telemetry/engine.js:etUserKey so admin_fleet can find
  // which identity an unresolved-user's telemetry file belongs to.
  // Format: first-letter + last-letter of name (lowercase). Two-letter
  // collision is possible across the fleet (e.g. Andrew Nemiroff and
  // Aaron Newman both → "an") — admin disambiguates via the auto-link
  // prompt when more than one identity matches.
  function _identityToUserKey(id) {
    if (!id) return null;
    var first = String(id.firstName || "").trim().toLowerCase().replace(/[^a-z0-9]/g, "");
    if (!first) {
      // Email-derived fallback: andrew_nemiroff@... → "an"
      var em = String(id.email || "");
      var local = em.split("@")[0] || "";
      var parts = local.toLowerCase().split(/[._-]/);
      first = parts[0] || "";
      var lastP = parts[parts.length - 1] || "";
      if (!first) return null;
      return lastP && lastP !== first ? first.charAt(0) + lastP.charAt(0) : first.charAt(0);
    }
    var firstInitial = first.charAt(0);
    var full = String(id.name || id.lastName || "").trim();
    var lastInitial = "";
    if (full) {
      var nameParts = full.split(/\s+/).filter(Boolean);
      if (nameParts.length >= 2) {
        var last = nameParts[nameParts.length - 1].toLowerCase().replace(/[^a-z0-9]/g, "");
        if (last) lastInitial = last.charAt(0);
      }
    }
    return lastInitial ? firstInitial + lastInitial : firstInitial;
  }
  // Returns array of [identityUserId, identityRecord] tuples whose
  // derived userKey matches the given one. Used to suggest re-linking
  // when an old identity's user_id became orphan after a wipe.
  function _identitiesForUserKey(userKey) {
    if (!userKey) return [];
    var hits = [];
    Object.keys(_lookup || {}).forEach(function (uid) {
      var id = _lookup[uid];
      if (_identityToUserKey(id) === userKey) hits.push([uid, id]);
    });
    return hits;
  }

  // 2026-05-23c: audience helpers shared across the push dialogs.
  // Three targeting modes:
  //   "this"  → audienceEmails: [target]            (per-user, current default)
  //   "all"   → audience: ["all"]                   (broadcast)
  //   "except"→ audience: ["all"] + excludes target (broadcast minus this user)
  // Override IDs include a suffix so multiple admins / re-pushes don't
  // collide and so the IDs are self-describing in the CDN file.
  function _buildAudienceFields(audienceMode, targetEmail) {
    if (audienceMode === "all") return { audience: ["all"] };
    if (audienceMode === "except") {
      return { audience: ["all"], audienceEmailExcludes: [targetEmail] };
    }
    return { audienceEmails: [targetEmail] };
  }
  function _audienceLabel(audienceMode, displayName) {
    if (audienceMode === "all") return "everyone";
    if (audienceMode === "except") return "everyone except " + displayName;
    return displayName;
  }
  function _audienceIdSuffix(audienceMode, userId) {
    if (audienceMode === "all") return "all";
    if (audienceMode === "except") return "except-" + userId;
    return userId;
  }
  function _audienceRadioHtml(formId) {
    // formId disambiguates radio groups when two dialogs are stacked.
    return '<label class="_eli3_af_radio"><input type="radio" name="' + formId + '" value="this" checked> ' +
        '<b>This user only</b></label><br>' +
      '<label class="_eli3_af_radio"><input type="radio" name="' + formId + '" value="all"> ' +
        '<b>Everyone</b> — broadcast to entire fleet</label><br>' +
      '<label class="_eli3_af_radio"><input type="radio" name="' + formId + '" value="except"> ' +
        '<b>Everyone except this user</b></label>';
  }

  // ── GitHub helpers ────────────────────────────────────────────────
  function _strToB64(s) {
    return btoa(unescape(encodeURIComponent(s)));
  }
  function _b64ToStr(b) {
    return decodeURIComponent(escape(atob(String(b || "").replace(/\s/g, ""))));
  }
  function _ghGet(path) {
    var url = "https://api.github.com/repos/" + GH_OWNER + "/" + GH_REPO +
      "/contents/" + encodeURIComponent(path) + "?ref=" + encodeURIComponent(GH_BRANCH) + "&t=" + Date.now();
    var headers = {
      "Accept": "application/vnd.github+json",
      "X-GitHub-Api-Version": "2022-11-28",
    };
    if (_pat) headers["Authorization"] = "Bearer " + _pat;
    return fetch(url, { cache: "no-store", headers: headers }).then(function (r) {
      if (r.status === 404) return null;
      if (!r.ok) return r.text().then(function (t) {
        throw new Error("GET " + path + ": HTTP " + r.status + " · " + t.slice(0, 200));
      });
      return r.json();
    });
  }
  function _ghPut(path, contentStr, message, existingSha) {
    if (!_pat) return Promise.reject(new Error("No GitHub PAT — import credentials first"));
    var url = "https://api.github.com/repos/" + GH_OWNER + "/" + GH_REPO + "/contents/" + encodeURIComponent(path);
    var body = { message: message, content: _strToB64(contentStr), branch: GH_BRANCH };
    if (existingSha) body.sha = existingSha;
    return fetch(url, {
      method: "PUT",
      headers: {
        "Authorization": "Bearer " + _pat,
        "Accept": "application/vnd.github+json",
        "X-GitHub-Api-Version": "2022-11-28",
        "Content-Type": "application/json",
      },
      body: JSON.stringify(body),
    }).then(function (r) {
      if (r.ok) return r.json();
      return r.text().then(function (t) {
        throw new Error("PUT " + path + ": HTTP " + r.status + " · " + t.slice(0, 200));
      });
    }).then(function (result) {
      // Fire-and-forget jsdelivr purge
      var purge = "https://purge.jsdelivr.net/gh/" + GH_OWNER + "/" + GH_REPO + "@" + GH_BRANCH + "/" + path;
      fetch(purge, { method: "GET" }).catch(function () {});
      return result;
    });
  }

  // 2026-05-23: DELETE a file from the CDN via GitHub Contents API.
  // Needs the file's current SHA (fetched via _ghGet) per GitHub's API
  // contract. Returns silently if the file doesn't exist (treats 404
  // as already-deleted).
  function _ghDelete(path, message) {
    if (!_pat) return Promise.reject(new Error("No GitHub PAT — import credentials first"));
    return _ghGet(path).then(function (r) {
      if (!r || !r.sha) return null; // already gone
      var url = "https://api.github.com/repos/" + GH_OWNER + "/" + GH_REPO + "/contents/" + encodeURIComponent(path);
      var body = { message: message, sha: r.sha, branch: GH_BRANCH };
      return fetch(url, {
        method: "DELETE",
        headers: {
          "Authorization": "Bearer " + _pat,
          "Accept": "application/vnd.github+json",
          "X-GitHub-Api-Version": "2022-11-28",
          "Content-Type": "application/json",
        },
        body: JSON.stringify(body),
      }).then(function (res) {
        if (res.ok) return res.json();
        return res.text().then(function (t) {
          throw new Error("DELETE " + path + ": HTTP " + res.status + " · " + t.slice(0, 200));
        });
      });
    });
  }

  // ── Credentials ───────────────────────────────────────────────────
  function _loadCredentials() {
    _pat = eli.compat.lsGet("eli_user_github_pat") || null;
    _password = eli.compat.lsGet("eli_admin_password") || null;
    try {
      _userIdentity = (eli.tools && typeof eli.tools.userIdentity === "function")
        ? eli.tools.userIdentity() : null;
    } catch (_e) {}
    return { hasPat: !!_pat, hasPassword: !!_password };
  }

  // ── Identity lookup (CDN encrypted) ──────────────────────────────
  function _fetchIdentityFromCdn() {
    return _ghGet(IDENTITY_PATH).then(function (r) {
      if (!r) return { lookup: {}, sha: null, isNew: true };
      _identitySha = r.sha;
      var content = _b64ToStr(r.content);
      var blob;
      try { blob = JSON.parse(content); }
      catch (e) { throw new Error("Identity file is not valid JSON: " + e.message); }
      if (!window._eliIsEncryptedBlob(blob)) {
        // Plain JSON (back-compat or pre-encryption state) — accept it.
        return { lookup: blob.identities || blob || {}, sha: r.sha, isNew: false };
      }
      if (!_password) throw new Error("Admin password missing — set eli_admin_password to decrypt identity map");
      return window._eliDecryptFromRepo(_password, blob).then(function (decrypted) {
        return { lookup: (decrypted && decrypted.identities) || {}, sha: r.sha, isNew: false, schemaVersion: decrypted.schemaVersion };
      });
    });
  }
  function _saveIdentityToCdn() {
    if (!_password) return Promise.reject(new Error("Admin password missing — cannot encrypt"));
    var payload = {
      schemaVersion: 1,
      encryptedAt: new Date().toISOString(),
      encryptedBy: (_userIdentity && _userIdentity.email) || "unknown",
      identities: _lookup,
    };
    return window._eliEncryptForRepo(_password, payload).then(function (blob) {
      var json = JSON.stringify(blob, null, 0);
      var msg = "admin_fleet: update identity map (" + Object.keys(_lookup).length + " users) @ " +
        new Date().toISOString().replace("T", " ").replace(/\..*/, "");
      return _ghPut(IDENTITY_PATH, json, msg, _identitySha).then(function (result) {
        _identitySha = result.content && result.content.sha;
        return true;
      });
    });
  }

  // ── Telemetry reading ─────────────────────────────────────────────
  // Telemetry files live at apndrewn/eli-data/usage/<userKey>.json
  // (per eli_telemetry's _githubPut → "usage/" + encodeURIComponent(userKey)).
  // userKey is the user's lowercase initials, e.g. "an", "jl" (per
  // etUserKey in eli_telemetry/engine.js).
  function _fetchAllTelemetry() {
    var url = "https://api.github.com/repos/" + GH_OWNER + "/" + GH_REPO + "/contents/usage?ref=" + encodeURIComponent(GH_BRANCH) + "&t=" + Date.now();
    var headers = {
      "Accept": "application/vnd.github+json",
      "X-GitHub-Api-Version": "2022-11-28",
    };
    if (_pat) headers["Authorization"] = "Bearer " + _pat;
    return fetch(url, { cache: "no-store", headers: headers }).then(function (r) {
      if (r.status === 404) return []; // usage folder doesn't exist yet
      if (!r.ok) return r.text().then(function (t) {
        throw new Error("List usage/: HTTP " + r.status + " · " + t.slice(0, 200));
      });
      return r.json();
    }).then(function (files) {
      // Filter: telemetry files are .json (skip .bak backups, hidden files)
      var telemetryFiles = (files || []).filter(function (f) {
        if (!f || f.type !== "file") return false;
        if (!/\.json$/.test(f.name)) return false;
        // Skip .bak files (created during clear operations)
        if (/\.bak/.test(f.name)) return false;
        return true;
      });
      var fetches = telemetryFiles.map(function (f) {
        var rawUrl = "https://raw.githubusercontent.com/" + GH_OWNER + "/" + GH_REPO + "/" + GH_BRANCH + "/usage/" + encodeURIComponent(f.name) + "?t=" + Date.now();
        return fetch(rawUrl, { cache: "no-store" }).then(function (r) {
          if (!r.ok) return null;
          return r.json();
        }).then(function (digest) {
          return { fileName: f.name, userKey: f.name.replace(/\.json$/, ""), digest: digest };
        }).catch(function () { return { fileName: f.name, userKey: f.name.replace(/\.json$/, ""), digest: null }; });
      });
      // 2026-05-23: drop ghost entries where the file fetch returned null.
