    var em = Array.isArray(entry.audienceEmails) ? entry.audienceEmails : null;
    var dom = Array.isArray(entry.audienceEmailDomains) ? entry.audienceEmailDomains : null;
    var uids = Array.isArray(entry.audienceUserIds) ? entry.audienceUserIds : null;
