  // most-specific positive gate first, with excludes surfaced separately.
  //
  // Result shape:
  //   {
  //     public:    [{ id, entry, excludes: [...] }],
  //     emails:    [{ id, entry, emails: [...], excludeCount: N }],
  //     domains:   [{ id, entry, domains: [...], excludeCount: N }],
  //     userIds:   [{ id, entry, userIds: [...], excludeCount: N }],
  //     tags:      [{ id, entry, tags:    [...], excludeCount: N }],
