      var emails = Array.isArray(t.audienceEmails) ? t.audienceEmails : null;
      var domains = Array.isArray(t.audienceEmailDomains) ? t.audienceEmailDomains : null;
      var uids = Array.isArray(t.audienceUserIds) ? t.audienceUserIds : null;
