    var emailHtml = '<span style="font-family:Monaco,monospace;font-size:10.5px;">' + _esc(email) + '</span>';
    if (matched) {
      return emailHtml +
        ' <span style="font-size:10px;color:#15803d;background:#dcfce7;padding:1px 5px;border-radius:3px;font-weight:700;" title="Resolved via identity lookup">' +
          _esc(_displayName(matched.userId)) +
