    //   2. _legacyUserKey helper for "AN-legacy" synthetic IDs
    //   3. Fall back to userId as filename (rare — would mean the
    //      user has telemetry stored at usage/<userId>.json which is
    //      unusual)
    var telemetryKey = _userKeyByUserId[userId];
    if (!telemetryKey) {
      var legacyKey = _legacyUserKey(userId);
      if (legacyKey) telemetryKey = legacyKey;
    }
    if (!telemetryKey) telemetryKey = userId; // last-resort
    var telemetryPath = "usage/" + telemetryKey + ".json";

    var bodyHtml =
      '<div class="_eli3_af_form">' +
        '<div class="_eli3_af_warn">⚠️ This deletes the telemetry file from the CDN. ' +
        'It does NOT affect the user\'s local install or stop them from running ELI. ' +
        'Their next telemetry push will recreate the file with current fleet data.' +
        '<br><br><b>Note:</b> telemetry files are shared per-install — if this user has the same email but a stale user_id (e.g. from a kernel auto-upgrade), deleting the file removes their entire history. ' +
        'To just refresh the fleet block instead, have the user force-push from Settings → Telemetry on their machine.</div>' +
        '<div class="_eli3_af_form_row">' +
          '<label>Display name</label>' +
          '<div class="_eli3_af_form_val_static">' + _esc(displayName) + '</div>' +
        '</div>' +
        '<div class="_eli3_af_form_row">' +
          '<label>Email</label>' +
          '<div class="_eli3_af_form_val_static">' + _esc(email) + '</div>' +
        '</div>' +
        '<div class="_eli3_af_form_row">' +
          '<label>User ID</label>' +
          '<div class="_eli3_af_form_val_static" style="font-family:monospace;font-size:11px;">' + _esc(userId) + '</div>' +
        '</div>' +
        '<div class="_eli3_af_form_row">' +
          '<label>What gets deleted</label>' +
          '<div style="font-size:11.5px;line-height:1.5;">' +
            (hasIdentity
              ? '<label class="_eli3_af_radio"><input type="checkbox" id="_af_del_identity" checked> ' +
                  'Identity record (email → UUID mapping in fleet-identity.enc.json)</label><br>'
              : '') +
            '<label class="_eli3_af_radio"><input type="checkbox" id="_af_del_telemetry" checked> ' +
              'Telemetry file from CDN: <code>' + _esc(telemetryPath) + '</code></label>' +
          '</div>' +
        '</div>' +
      '</div>';

    showEliDialog({
      variant: "warning",
      icon: "🗑",
      title: "Delete user from fleet",
      body: bodyHtml,
      buttons: [
        {
          label: "Cancel",
          cls: "btn-secondary",
          onclick: function (e, ov) {
            if (ov && ov.parentNode) ov.parentNode.removeChild(ov);
          },
        },
        {
          label: "Delete",
          cls: "btn-action _eli3_af_btn_danger",
          onclick: function (e, overlay) {
            var delIdentityEl = document.getElementById("_af_del_identity");
            var delTelemetryEl = document.getElementById("_af_del_telemetry");
            var delIdentity = !!(delIdentityEl && delIdentityEl.checked);
            var delTelemetry = !!(delTelemetryEl && delTelemetryEl.checked);
            if (!delIdentity && !delTelemetry) {
              _toast("Pick at least one thing to delete", "warn");
              return false;
            }
            _toast("⏳ Deleting…", "info");
            var chain = Promise.resolve();
            if (delIdentity && hasIdentity) {
              chain = chain.then(function () {
                delete _lookup[userId];
                return _saveIdentityToCdn();
              });
            }
            if (delTelemetry) {
              chain = chain.then(function () {
                return _ghDelete(
                  telemetryPath,
                  "admin_fleet: delete telemetry for " + telemetryKey + " @ " +
                    new Date().toISOString().replace("T", " ").replace(/\..*/, "")
                );
              });
            }
            chain.then(function () {
              _toast("✅ Deleted " + displayName + (delIdentity && delTelemetry ? " (identity + telemetry)" : delIdentity ? " (identity)" : " (telemetry)"), "ok");
              // Drop the local telemetry cache too so the dashboard re-render
              // doesn't show the deleted user as a ghost.
              delete _telemetryByUserId[userId];
              delete _telemetryRowsByUserKey[telemetryKey];
              _launch(true); // hard refresh from CDN
            }).catch(function (err) {
              _toast("Delete failed: " + (err && err.message || "unknown"), "err");
              // Re-fetch in case partial delete left things inconsistent.
              _launch(true);
            });
            if (overlay && overlay.parentNode) overlay.parentNode.removeChild(overlay);
          },
        },
      ],
    });
  }

  function _showIdentityEditor(userId, isNew) {
    if (typeof showEliDialog !== "function") {
      _toast("showEliDialog unavailable", "err");
      return;
    }
    var existing = _identityFor(userId) || {};
    var fleet = _telemetryByUserId[userId] || {};
    var prefilledInitials = fleet.initials || (userId.split("-")[0]) || "";
    var firstHint = "";
    var lastHint = "";
    if (prefilledInitials.length >= 1) firstHint = prefilledInitials.charAt(0);
    if (prefilledInitials.length >= 2) lastHint = prefilledInitials.charAt(1);

    var bodyHtml =
      '<div class="_eli3_af_form">' +
        '<div class="_eli3_af_form_row">' +
          '<label>User ID</label>' +
          '<div class="_eli3_af_form_val_static">' + _esc(userId) + '</div>' +
        '</div>' +
        '<div class="_eli3_af_form_row">' +
          '<label>Initials hint</label>' +
          '<div class="_eli3_af_form_val_static">' + _esc(prefilledInitials || "—") + '</div>' +
        '</div>' +
        '<div class="_eli3_af_form_row">' +
          '<label>Email <span class="_eli3_af_req">*</span></label>' +
          '<input type="email" id="_af_form_email" value="' + _esc(existing.email || "") + '" placeholder="user@example.com" required>' +
        '</div>' +
        '<div class="_eli3_af_form_row">' +
          '<label>First name</label>' +
          '<input type="text" id="_af_form_first" value="' + _esc(existing.firstName || (firstHint ? firstHint + "..." : "")) + '" placeholder="Jared">' +
        '</div>' +
        '<div class="_eli3_af_form_row">' +
          '<label>Last name</label>' +
          '<input type="text" id="_af_form_last" value="' + _esc(existing.lastName || (lastHint ? "..." + lastHint : "")) + '" placeholder="Lerner">' +
        '</div>' +
        '<div class="_eli3_af_form_row">' +
          '<label>Role</label>' +
          '<select id="_af_form_role">' +
            ['', 'admin', 'attorney', 'intern', 'observer', 'other'].map(function (r) {
              var sel = (existing.role === r || (!existing.role && !r)) ? " selected" : "";
              return '<option value="' + r + '"' + sel + '>' + (r || "—") + '</option>';
            }).join('') +
          '</select>' +
        '</div>' +
        '<div class="_eli3_af_form_row">' +
          '<label>Team</label>' +
          '<input type="text" id="_af_form_team" value="' + _esc(existing.team || "") + '" placeholder="(optional)">' +
        '</div>' +
        '<div class="_eli3_af_form_row">' +
          '<label>Status</label>' +
          '<select id="_af_form_status">' +
            ['active', 'trial', 'offboarded'].map(function (s) {
              var sel = (existing.status || "active") === s ? " selected" : "";
              return '<option value="' + s + '"' + sel + '>' + s + '</option>';
            }).join('') +
          '</select>' +
        '</div>' +
        '<div class="_eli3_af_form_row">' +
          '<label>Notes</label>' +
          '<textarea id="_af_form_notes" rows="2" placeholder="(optional)">' + _esc(existing.notes || "") + '</textarea>' +
        '</div>' +
      '</div>';

    showEliDialog({
      variant: "neutral",
      size: "wide",
      icon: isNew ? "🆕" : "✏️",
      title: isNew ? "Identify new user" : "Edit user",
      body: bodyHtml,
      buttons: [
        {
          label: "Cancel",
          cls: "btn-secondary",
          onclick: function (e, ov) {
            if (ov && ov.parentNode) ov.parentNode.removeChild(ov);
          },
        },
        {
          label: isNew ? "Save identity" : "Save changes",
          cls: "btn-action btn-primary",
          onclick: function (e, overlay) {
            var emailEl = document.getElementById("_af_form_email");
            if (!emailEl) {
              _toast("Form bug: email input not found in DOM. Reload + retry.", "err");
              try { console.log("[admin_fleet] _af_form_email element missing", { overlayChildren: overlay && overlay.querySelectorAll && overlay.querySelectorAll("input").length }); } catch (_) {}
              return false;
            }
            var rawEmail = String(emailEl.value || "");
            var email = rawEmail.trim();
            if (!email) {
              _toast("Email required (the field is empty)", "err");
              return false;
            }
            if (!/@/.test(email)) {
              _toast("Email required — looks invalid: \"" + email + "\"", "err");
              return false;
            }
            // 2026-05-23: duplicate-email detection. If the same email is
            // already mapped to a DIFFERENT userId, prompt to migrate.
            // This handles the legacy→new migration cleanly: you identify
            // "JL-legacy" with jared@... → later Jared migrates → his new
            // telemetry has user_id "JL-2b9f1c8e" → you identify the new
            // entry with the same email → we detect + offer to delete the
            // old "JL-legacy" lookup row.
            var emailLc = email.toLowerCase();
            var duplicateUserId = null;
            Object.keys(_lookup).forEach(function (k) {
              if (k === userId) return;
              var v = _lookup[k];
              if (v && v.email && String(v.email).toLowerCase() === emailLc) {
                duplicateUserId = k;
              }
            });
            var record = {
              email: email,
              firstName: (document.getElementById("_af_form_first").value || "").trim(),
              lastName:  (document.getElementById("_af_form_last").value || "").trim(),
              role:      document.getElementById("_af_form_role").value || "",
              team:      (document.getElementById("_af_form_team").value || "").trim(),
              status:    document.getElementById("_af_form_status").value || "active",
              notes:     (document.getElementById("_af_form_notes").value || "").trim(),
              initials:  prefilledInitials,
              addedAt:   existing.addedAt || (duplicateUserId && _lookup[duplicateUserId].addedAt) || new Date().toISOString(),
              lastUpdated: new Date().toISOString(),
            };

            function _doSave(removeOldKey) {
              if (removeOldKey && duplicateUserId) {
                // Carry forward notes/role/team if the new form left them blank.
                var old = _lookup[duplicateUserId] || {};
                if (!record.role  && old.role)  record.role  = old.role;
                if (!record.team  && old.team)  record.team  = old.team;
                if (!record.notes && old.notes) record.notes = old.notes;
                delete _lookup[duplicateUserId];
              }
              _lookup[userId] = record;
              _toast("⏳ Saving identity map…", "info");
              _saveIdentityToCdn().then(function () {
                _toast(removeOldKey
                  ? "✅ Identity merged (" + duplicateUserId + " → " + userId + ")"
                  : "✅ Identity saved", "ok");
                _renderDashboard();
              }).catch(function (err) {
                _toast("Save failed: " + err.message, "err");
                // Revert local changes
                delete _lookup[userId];
                if (existing && existing.email) _lookup[userId] = existing;
                if (removeOldKey && duplicateUserId) _lookup[duplicateUserId] = (_lookup[duplicateUserId] || record);
              });
            }

            if (duplicateUserId && typeof showEliDialog === "function") {
              if (overlay && overlay.parentNode) overlay.parentNode.removeChild(overlay);
              showEliDialog({
                variant: "warning",
                icon: "🔀",
                title: "Same email already identified",
                paragraphs: [
                  "<b>" + _esc(email) + "</b> is already mapped to <code>" + _esc(duplicateUserId) + "</code>.",
                  "This usually means the user migrated to a new kernel (e.g., <code>JL-legacy</code> → <code>" + _esc(userId) + "</code>) and now has two entries — the legacy one and the new UUID-keyed one.",
                  "Merge the old entry into this new one? Old key will be deleted; notes / role / team carry forward.",
                ],
                buttons: [
                  { label: "Keep both (manual cleanup later)", cls: "btn-secondary", onclick: function (e2, ov) {
                    _doSave(false);
                    if (ov && ov.parentNode) ov.parentNode.removeChild(ov);
                  }},
                  { label: "Merge — delete " + duplicateUserId, cls: "btn-action btn-primary", onclick: function (e2, ov) {
                    _doSave(true);
                    if (ov && ov.parentNode) ov.parentNode.removeChild(ov);
                  }},
                ],
              });
              return;
            }
            _doSave(false);
            if (overlay && overlay.parentNode) overlay.parentNode.removeChild(overlay);
          },
        },
      ],
    });
  }

  // ── Dialog: setting change push ──────────────────────────────────
  function _showSettingPusher(userId, preselectedKey) {
    if (typeof showEliDialog !== "function") return;
    var id = _identityFor(userId);
    if (!id || !id.email) {
      _toast("Identify user first (need their email)", "err");
      return;
    }
    var fleet = _telemetryByUserId[userId] || {};
    var currentSettings = fleet.settings || {};
    // 2026-05-23c: registry snapshot — drives whether a key needs encrypted
    // push and what the type/options are. dump() is local to admin's machine
    // but all admin-pushable settings register on every kernel.
    var localRegistry = {};
    try {
      if (window.eli && window.eli.settings && typeof window.eli.settings.dump === "function") {
        localRegistry = window.eli.settings.dump() || {};
      }
    } catch (_e) {}
    // If the caller preselected a key that needs encrypted push, fork to
    // the dedicated encrypted dialog. The regular flow handles plain pushes.
    if (preselectedKey && localRegistry[preselectedKey] && localRegistry[preselectedKey].adminPushable === "encrypted") {
      return _showEncryptedSettingPusher(userId, preselectedKey);
    }

    // 2026-05-23c: build KNOWN_SETTINGS from the local registry (every
    // adminPushable: true key) — fold in known special cases (ai_model
    // options come from the target user's ai_model_list).
    // Encrypted-only settings (adminPushable: "encrypted") are NOT in
    // this list — they have their own dedicated dialog.
    //
    // 2026-05-23c+: TYPE_MAP fallback. The kernel's eli.settings.dump()
    // doesn't include the registry's `type` field — so we can't infer
    // it from localRegistry. Without a type, every value gets pushed as
    // a string (expand_width = "700" instead of 700, light_mode = "false"
    // instead of false). This map covers the known settings; unknown
    // keys fall through to "string" with no cast (admin can still type
    // a JSON-y value but it'll arrive as text — flag for follow-up).
    var TYPE_MAP = {
      ai_model: "string", ai_temperature: "number", ai_timeout_ms: "number",
      ai_thinking_budget: "number", ai_allow_streaming: "boolean",
      ai_model_list: "string[]",
      expand_width: "number", expand_threshold: "number",
      debug_mode: "boolean",
      light_mode: "boolean", header_theme_index: "number",
      minimize_feed: "boolean", auto_hide_sidebar: "boolean",
      auto_expand_window: "boolean", auto_check_tools: "boolean",
      show_expand_pill: "boolean", language: "string",
    };
    var KNOWN_SETTINGS = (function () {
      var out = [];
      Object.keys(localRegistry).forEach(function (k) {
        var entry = localRegistry[k];
        if (!entry || entry.adminPushable !== true) return;
        var labelMap = {
          ai_model: "AI Model",
          ai_temperature: "AI Temperature",
          ai_timeout_ms: "AI Timeout (ms)",
          ai_thinking_budget: "AI Thinking Budget",
          ai_allow_streaming: "AI Streaming",
          ai_model_list: "AI Model List",
          expand_width: "Expand Width",
          expand_threshold: "Expand Threshold",
          debug_mode: "Debug Mode",
          light_mode: "Light Mode",
          header_theme_index: "Header Theme Index",
          minimize_feed: "Minimize Feed on Start",
          auto_hide_sidebar: "Auto-Hide Sidebar",
          auto_expand_window: "Auto-Expand Window",
          auto_check_tools: "Auto-Check Tool Updates",
          show_expand_pill: "Show Expand Pill",
          language: "UI Language",
        };
        // entry.type isn't surfaced by dump() — fall back to TYPE_MAP for
        // the known keys, then to "string" as last resort.
        var type = entry.type || TYPE_MAP[k] || "string";
        var item = { key: k, label: labelMap[k] || k, type: type };
        if (type === "boolean") item.options = [true, false];
        if (k === "ai_model") {
          var userList = (currentSettings && Array.isArray(currentSettings.ai_model_list)) ? currentSettings.ai_model_list : null;
          if (userList && userList.length) {
            item.options = userList.slice();
          } else {
            var ownList = (window.eli && window.eli.settings && typeof window.eli.settings.get === "function")
              ? window.eli.settings.get("ai_model_list")
              : null;
            if (Array.isArray(ownList) && ownList.length) item.options = ownList.slice();
          }
        }
        out.push(item);
      });
      // Stable order for the dropdown.
      out.sort(function (a, b) { return a.label < b.label ? -1 : a.label > b.label ? 1 : 0; });
      return out;
    })();
    if (!KNOWN_SETTINGS.length) {
      _toast("No plain-pushable settings registered yet (only target has them after they boot post-2026-05-23c kernel)", "warn");
      return;
    }

    var rows = KNOWN_SETTINGS.map(function (s) {
      var cur = currentSettings.hasOwnProperty(s.key) ? currentSettings[s.key] : "—";
      var sel = (preselectedKey && preselectedKey === s.key) ? ' selected' : '';
      return '<option value="' + _esc(s.key) + '" data-type="' + s.type + '"' +
        (s.options ? ' data-has-options="1"' : '') + sel + '>' +
        _esc(s.label) + ' (current: ' + _esc(String(cur)) + ')</option>';
    }).join("");

    // Detect legacy kernel — no fleet block means user hasn't booted with
    // post-2026-05-23 kernel yet. Their eli.settings provider doesn't
    // exist → set_setting silently no-ops on their machine.
    var isLegacyTarget = !fleet || !fleet.kernelVersion;
    var legacyWarn = isLegacyTarget
      ? '<div class="_eli3_af_warn">⚠️ <b>This user is on a pre-fleet kernel.</b> ' +
        'Settings push will silently no-op on their machine until they import the new kernel snippet and reload. ' +
        'Tool actions (disable / enable / re-download) still work normally.</div>'
      : "";

    // First setting in the list is the default selection — render the
    // value field based on whether it has options. onchange of the key
    // dropdown will swap the value field between <input> and <select>.
    //
    // 2026-05-23c: ai_model gets a special "+ add new model…" option
    // that reveals a text input. Pushing a new model emits TWO actions
    // in one override: append the value to ai_model_list, then set
    // ai_model to it. Means admin can grow the per-user model list
    // without a separate ai_model_list push step.
    var ADD_NEW_MARKER = "__ADD_NEW__";
    function _buildValueFieldHtml(settingKey) {
      var s = KNOWN_SETTINGS.find(function (x) { return x.key === settingKey; });
      if (s && s.options && s.options.length) {
        // Dropdown of valid values
        var opts = s.options.map(function (v) {
          return '<option value="' + _esc(String(v)) + '">' + _esc(String(v)) + '</option>';
        }).join("");
        // ai_model: also append an "+ add new" choice. Other options-driven
        // settings (e.g. booleans) don't need it.
        if (settingKey === "ai_model") {
          opts += '<option value="' + ADD_NEW_MARKER + '">＋ add new model…</option>';
        }
        return '<select id="_af_set_val">' + opts + '</select>' +
          (settingKey === "ai_model"
            ? '<input type="text" id="_af_set_val_new" placeholder="e.g., gemini-3.5-pro" ' +
              'style="display:none;margin-top:6px;" autocomplete="off">'
            : '');
      }
      // Free-text fallback
      return '<input type="text" id="_af_set_val" placeholder="e.g., gemini-3.1-pro">';
    }
    var initialKey = (preselectedKey && KNOWN_SETTINGS.find(function (s) { return s.key === preselectedKey; }))
      ? preselectedKey
      : KNOWN_SETTINGS[0].key;

    var bodyHtml =
      '<div class="_eli3_af_form">' +
        legacyWarn +
        '<div class="_eli3_af_form_row">' +
          '<label>User</label>' +
          '<div class="_eli3_af_form_val_static">' + _esc(_displayName(userId)) + ' (' + _esc(id.email) + ')</div>' +
        '</div>' +
        '<div class="_eli3_af_form_row">' +
          '<label>Setting</label>' +
          '<select id="_af_set_key">' + rows + '</select>' +
        '</div>' +
        '<div class="_eli3_af_form_row">' +
          '<label>New value</label>' +
          '<div id="_af_set_val_wrap">' + _buildValueFieldHtml(initialKey) + '</div>' +
        '</div>' +
        '<div class="_eli3_af_form_row">' +
          '<label>Mode</label>' +
          '<div>' +
            '<label class="_eli3_af_radio"><input type="radio" name="_af_set_mode" value="reset" checked> ' +
              '<b>Reset</b> — push to user pref (editable after)</label><br>' +
            '<label class="_eli3_af_radio"><input type="radio" name="_af_set_mode" value="true"> ' +
              '<b>Force</b> — locked, user can\'t change</label><br>' +
            '<label class="_eli3_af_radio"><input type="radio" name="_af_set_mode" value="false"> ' +
              '<b>Soft</b> — only applies if user has no pref</label>' +
          '</div>' +
        '</div>' +
        '<div class="_eli3_af_form_row">' +
          '<label>Audience</label>' +
          '<div>' + _audienceRadioHtml("_af_set_aud") + '</div>' +
        '</div>' +
        '<div class="_eli3_af_form_row">' +
          '<label>Reason (note)</label>' +
          '<input type="text" id="_af_set_reason" placeholder="(optional admin note)">' +
        '</div>' +
      '</div>';

    showEliDialog({
      variant: "neutral",
      size: "wide",
      icon: "⚙️",
      title: "Push setting change",
      body: bodyHtml,
      onMount: function (overlay) {
        // Wire onchange on setting key — swap value field when the
        // selected setting has options (e.g., ai_model → dropdown of
        // valid models from user's ai_model_list).
        var keyEl = overlay.querySelector("#_af_set_key");
        var wrapEl = overlay.querySelector("#_af_set_val_wrap");
        // Reveal the "type a new model" input when admin picks the
        // "+ add new model…" option in the ai_model dropdown.
        function _wireAddNewToggle() {
          var valEl = overlay.querySelector("#_af_set_val");
          var newEl = overlay.querySelector("#_af_set_val_new");
          if (!valEl || !newEl) return;
          valEl.addEventListener("change", function () {
            if (valEl.value === ADD_NEW_MARKER) {
              newEl.style.display = "block";
              newEl.focus();
            } else {
              newEl.style.display = "none";
              newEl.value = "";
            }
          });
        }
        if (keyEl && wrapEl) {
          keyEl.addEventListener("change", function () {
            wrapEl.innerHTML = _buildValueFieldHtml(keyEl.value);
            _wireAddNewToggle();
          });
        }
        _wireAddNewToggle();
      },
      buttons: [
        {
          label: "Cancel",
          cls: "btn-secondary",
          onclick: function (e, ov) {
            if (ov && ov.parentNode) ov.parentNode.removeChild(ov);
          },
        },
        {
          // Label stays neutral — audience is selected in the form, so the
          // button can't bake in the target name without making the
          // audience radio feel decorative.
          label: "Push",
          cls: "btn-action btn-primary",
          onclick: function (e, overlay) {
            var key = document.getElementById("_af_set_key").value;
            var rawVal = (document.getElementById("_af_set_val").value || "").trim();
            var modeStr = (document.querySelector('input[name="_af_set_mode"]:checked') || {}).value || "reset";
            var force = (modeStr === "true") ? true : (modeStr === "reset" ? "reset" : false);
            var audMode = (document.querySelector('input[name="_af_set_aud"]:checked') || {}).value || "this";
            var audFields = _buildAudienceFields(audMode, id.email);
            var audLabel = _audienceLabel(audMode, _displayName(userId));
            var audIdSuffix = _audienceIdSuffix(audMode, userId);
            var reason = (document.getElementById("_af_set_reason").value || "").trim();

            // 2026-05-23c: special path — admin picked "+ add new model…".
            // Build a dual-action override: append to ai_model_list, then
            // set ai_model to the new value. Single push, atomic apply.
            // For broadcast modes ("all"/"except"), targetList falls back
            // to admin's own ai_model_list since there's no single "target".
            if (key === "ai_model" && rawVal === ADD_NEW_MARKER) {
              var newModel = (document.getElementById("_af_set_val_new") || { value: "" }).value.trim();
              if (!newModel) { _toast("Type the new model name", "err"); return false; }
              var targetList;
              if (audMode === "this") {
                targetList = (currentSettings && Array.isArray(currentSettings.ai_model_list))
                  ? currentSettings.ai_model_list.slice()
                  : (function () {
                      var s = KNOWN_SETTINGS.find(function (x) { return x.key === "ai_model"; });
                      return s && s.options ? s.options.slice() : [];
                    })();
              } else {
                // Broadcast: use admin's own list as the floor — receivers'
                // lists will be REPLACED (set_setting overwrites) with this
                // composite. Trade-off: a colleague's bespoke models get
                // wiped. Document this; admin chose broadcast knowingly.
                var ownList = (window.eli && window.eli.settings && typeof window.eli.settings.get === "function")
                  ? window.eli.settings.get("ai_model_list")
                  : null;
                targetList = Array.isArray(ownList) ? ownList.slice() : [];
              }
              if (targetList.indexOf(newModel) === -1) targetList.push(newModel);

              var dualId = "fleet-addmodel-" + audIdSuffix + "-" + Date.now();
              var dualEntry = Object.assign({
                id: dualId,
                actions: [
                  { type: "set_setting", key: "ai_model_list", value: targetList, force: force },
                  { type: "set_setting", key: "ai_model",      value: newModel,   force: force },
                ],
                pushedAt: new Date().toISOString(),
                pushedBy: (_userIdentity && _userIdentity.email) || "unknown",
              }, audFields);
              if (reason) dualEntry.note = reason;

              _toast("⏳ Pushing new model + selecting it…", "info");
              _pushOverride(dualEntry).then(function () {
                _toast("✅ Added " + newModel + " to " + audLabel + "'s list and selected it", "ok");
                _renderDashboard();
              }).catch(function (err) {
                _toast("Push failed: " + (err && err.message || "unknown"), "err");
              });

              if (overlay && overlay.parentNode) overlay.parentNode.removeChild(overlay);
              return;
            }

            if (!rawVal) { _toast("Value required", "err"); return false; }
            // Type-cast based on the setting's declared type
            var typeStr = document.querySelector("#_af_set_key option:checked").getAttribute("data-type");
            var val = rawVal;
            if (typeStr === "number") val = Number(rawVal);
            else if (typeStr === "boolean") val = (rawVal === "true" || rawVal === "1");

            var overrideId = "fleet-set-" + key + "-" + audIdSuffix + "-" + Date.now();
            var entry = Object.assign({
              id: overrideId,
              actions: [{
                type: "set_setting",
                key: key,
                value: val,
                force: force,
              }],
              pushedAt: new Date().toISOString(),
              pushedBy: (_userIdentity && _userIdentity.email) || "unknown",
            }, audFields);
            if (reason) entry.note = reason;

            _toast("⏳ Pushing override…", "info");
            _pushOverride(entry).then(function () {
              _toast("✅ Pushed " + key + " → " + val + " to " + audLabel, "ok");
              _renderDashboard();
            }).catch(function (err) {
              _toast("Push failed: " + err.message, "err");
            });

            if (overlay && overlay.parentNode) overlay.parentNode.removeChild(overlay);
          },
        },
      ],
    });
  }

  // ── Dialog: encrypted setting push ──────────────────────────────
  // 2026-05-23c: sensitive settings (admin_password, github_pat, etc.)
  // never appear on the CDN in plaintext. The admin types a NEW value
  // here; we encrypt with the admin's local admin_password and emit a
  // set_setting_encrypted action containing ciphertext. The target
  // decrypts locally and writes via eli.settings.set.
  function _showEncryptedSettingPusher(userId, settingKey) {
    if (typeof showEliDialog !== "function") return;
    var id = _identityFor(userId);
    if (!id || !id.email) {
      _toast("Identify user first (need their email)", "err");
      return;
    }
    if (typeof window._eliEncryptForRepo !== "function") {
      _toast("Encrypt helper missing — kernel may be pre-2026-05-23c", "err");
      return;
    }
    if (!_password) {
      _toast("Your admin_password isn't loaded — import a credentials bundle first", "err");
      return;
    }
    // Label hint pulled from the registry's `describe` (set on register).
    var localRegistry = {};
    try { localRegistry = window.eli.settings.dump() || {}; } catch (_e) {}
    var describe = (localRegistry[settingKey] && localRegistry[settingKey].describe) || "";
    var fleet = _telemetryByUserId[userId] || {};
    var isLegacyTarget = !fleet || !fleet.kernelVersion;
    var legacyWarn = isLegacyTarget
      ? '<div class="_eli3_af_warn">⚠️ This user is on a pre-fleet kernel. The encrypted push will only apply once they import the new kernel snippet and reload.</div>'
      : "";

    var bodyHtml =
      '<div class="_eli3_af_form">' +
        legacyWarn +
        '<div class="_eli3_af_form_row">' +
          '<label>User</label>' +
          '<div class="_eli3_af_form_val_static">' + _esc(_displayName(userId)) + ' (' + _esc(id.email) + ')</div>' +
        '</div>' +
        '<div class="_eli3_af_form_row">' +
          '<label>Setting</label>' +
          '<div class="_eli3_af_form_val_static"><b>🔐 ' + _esc(settingKey) + '</b>' +
            (describe ? ' — <span style="opacity:0.7">' + _esc(describe) + '</span>' : '') +
          '</div>' +
        '</div>' +
        '<div class="_eli3_af_form_row">' +
          '<label>Current value</label>' +
          '<div class="_eli3_af_form_val_static" style="opacity:0.6;font-style:italic">(encrypted — push-only, never visible to admin)</div>' +
        '</div>' +
        '<div class="_eli3_af_form_row">' +
          '<label>New value <span class="_eli3_af_req">*</span></label>' +
          '<input type="text" id="_af_enc_val" placeholder="will be encrypted locally before push" autocomplete="off">' +
        '</div>' +
        '<div class="_eli3_af_form_row">' +
          '<label>Mode</label>' +
          '<div>' +
            '<label class="_eli3_af_radio"><input type="radio" name="_af_enc_mode" value="reset" checked> ' +
              '<b>Reset</b> — push to user pref (editable after)</label><br>' +
            '<label class="_eli3_af_radio"><input type="radio" name="_af_enc_mode" value="true"> ' +
              '<b>Force</b> — locked, user can\'t change</label><br>' +
            '<label class="_eli3_af_radio"><input type="radio" name="_af_enc_mode" value="false"> ' +
              '<b>Soft</b> — only applies if user has no pref</label>' +
          '</div>' +
        '</div>' +
        '<div class="_eli3_af_form_row">' +
          '<label>Audience</label>' +
          '<div>' + _audienceRadioHtml("_af_enc_aud") + '</div>' +
        '</div>' +
        '<div class="_eli3_af_form_row">' +
          '<label>Reason (note)</label>' +
          '<input type="text" id="_af_enc_reason" placeholder="(optional admin note — NOT encrypted, NOT sent to CDN)">' +
        '</div>' +
        '<div style="margin-top:8px;padding:6px 8px;background:#f1f5f9;border-radius:4px;font-size:11px;color:#475569;">' +
          '🔒 The value will be encrypted with your admin_password using AES-GCM and shipped as ciphertext. ' +
          'It is decrypted on the target user\'s machine using their local admin_password.' +
        '</div>' +
      '</div>';

    showEliDialog({
      variant: "neutral",
      size: "wide",
      icon: "🔐",
      title: "Push encrypted setting",
      body: bodyHtml,
      buttons: [
        {
          label: "Cancel",
          cls: "btn-secondary",
          onclick: function (e, ov) {
            if (ov && ov.parentNode) ov.parentNode.removeChild(ov);
          },
        },
        {
          label: "Encrypt & push",
          cls: "btn-action btn-primary",
          onclick: function (e, overlay) {
            var rawVal = (document.getElementById("_af_enc_val").value || "").trim();
            if (!rawVal) { _toast("New value required", "err"); return false; }
            var modeStr = (document.querySelector('input[name="_af_enc_mode"]:checked') || {}).value || "reset";
            var force = (modeStr === "true") ? true : (modeStr === "reset" ? "reset" : false);
            var audMode = (document.querySelector('input[name="_af_enc_aud"]:checked') || {}).value || "this";
            var audFields = _buildAudienceFields(audMode, id.email);
            var audLabel = _audienceLabel(audMode, _displayName(userId));
            var audIdSuffix = _audienceIdSuffix(audMode, userId);
            var reason = (document.getElementById("_af_enc_reason").value || "").trim();

            _toast("⏳ Encrypting…", "info");
            // Envelope wraps the value so we can extend later without
            // breaking the wire format (e.g., add `pushed_by`).
            // SECURITY NOTE on broadcast encrypted pushes: the ciphertext
            // is decrypted on each target with their LOCAL admin_password.
            // All targets in the fleet share the same admin_password
            // (it's how they were provisioned), so the same blob decrypts
            // for everyone. If you ever shard admin_password by group,
            // re-think this path before broadcasting encrypted settings.
            window._eliEncryptForRepo(_password, { v: 1, value: rawVal }).then(function (ciphertext) {
              var overrideId = "fleet-encset-" + settingKey + "-" + audIdSuffix + "-" + Date.now();
              var entry = Object.assign({
                id: overrideId,
                actions: [{
                  type: "set_setting_encrypted",
                  key: settingKey,
                  ciphertext: ciphertext,
                  force: force,
                }],
                pushedAt: new Date().toISOString(),
                pushedBy: (_userIdentity && _userIdentity.email) || "unknown",
              }, audFields);
              if (reason) entry.note = reason;

              _toast("⏳ Pushing encrypted override…", "info");
              return _pushOverride(entry);
            }).then(function () {
              _toast("✅ Encrypted push of " + settingKey + " queued for " + audLabel, "ok");
              _renderDashboard();
            }).catch(function (err) {
              _toast("Encrypted push failed: " + (err && err.message || "unknown"), "err");
            });

            if (overlay && overlay.parentNode) overlay.parentNode.removeChild(overlay);
          },
        },
      ],
    });
  }

  // ── Dialog: notice push ──────────────────────────────────────────
  // 2026-05-23c+: free-form message broadcast. Composes a `notice` action
  // override which target's eli-admin renders via showEliDialog. Same
  // audience picker as setting pushes (this user / all / all except).
  //
  // Pass userId=null for pure broadcast (header "Broadcast" button) —
  // dialog shows audience radios with "Everyone" as the only sensible
  // default (other modes need a target user to scope around).
  function _showNoticePusher(userId) {
    if (typeof showEliDialog !== "function") return;
    var id = userId ? _identityFor(userId) : null;
    if (userId && (!id || !id.email)) {
      _toast("Identify user first (need their email)", "err");
      return;
    }
    var hasTarget = !!id;
    // Headline text — adapts to context.
    var headline = hasTarget
      ? "Send notice to " + _esc(_displayName(userId)) + " (or broader audience)"
      : "Broadcast notice to fleet";

    // Audience picker — only show options that make sense for the context.
    // No target → "all" is forced (no "this user" or "except").
    var audienceHtml = hasTarget
      ? _audienceRadioHtml("_af_notice_aud")
      : '<label class="_eli3_af_radio"><input type="radio" name="_af_notice_aud" value="all" checked> ' +
          '<b>Everyone</b> — broadcast to entire fleet</label>';

    var bodyHtml =
      '<div class="_eli3_af_form">' +
        (hasTarget
          ? '<div class="_eli3_af_form_row">' +
              '<label>User</label>' +
              '<div class="_eli3_af_form_val_static">' + _esc(_displayName(userId)) + ' (' + _esc(id.email) + ')</div>' +
            '</div>'
          : '') +
        '<div class="_eli3_af_form_row">' +
          '<label>Title <span class="_eli3_af_req">*</span></label>' +
          '<input type="text" id="_af_notice_title" placeholder="e.g., Heads up — maintenance Sunday 6pm" autocomplete="off">' +
        '</div>' +
        '<div class="_eli3_af_form_row">' +
          '<label>Message <span class="_eli3_af_req">*</span></label>' +
          '<textarea id="_af_notice_body" rows="5" placeholder="HTML allowed (paragraphs, lists, links). Plain text also works — newlines render as you type."></textarea>' +
        '</div>' +
        '<div class="_eli3_af_form_row">' +
          '<label>Dismiss button</label>' +
          '<input type="text" id="_af_notice_dismiss" placeholder="OK" value="OK">' +
        '</div>' +
        '<div class="_eli3_af_form_row">' +
          '<label>Audience</label>' +
          '<div>' + audienceHtml + '</div>' +
        '</div>' +
        '<div class="_eli3_af_form_row">' +
          '<label>Reason (note)</label>' +
          '<input type="text" id="_af_notice_reason" placeholder="(optional admin note — NOT shown to recipients)">' +
        '</div>' +
        '<div style="margin-top:8px;padding:6px 8px;background:#f1f5f9;border-radius:4px;font-size:11px;color:#475569;">' +
          '💡 Notice fires once per recipient on their next ELI reload (or recurring poll, if enabled). ' +
          'Targets that already received it before are skipped via applied-marker — same as any other override.' +
        '</div>' +
      '</div>';

    showEliDialog({
      variant: "neutral",
      size: "wide",
      icon: "📢",
      title: headline,
      body: bodyHtml,
      onMount: function (overlay) {
        // Convert plain-text newlines to <br> at submit time — but for
        // the textarea itself, no transformation needed during edit.
        var titleEl = overlay.querySelector("#_af_notice_title");
        if (titleEl) setTimeout(function () { titleEl.focus(); }, 50);
      },
      buttons: [
        {
          label: "Cancel",
          cls: "btn-secondary",
          onclick: function (e, ov) {
            if (ov && ov.parentNode) ov.parentNode.removeChild(ov);
          },
        },
        {
          label: "Send",
          cls: "btn-action btn-primary",
          onclick: function (e, overlay) {
            var title = (document.getElementById("_af_notice_title").value || "").trim();
            var body  = (document.getElementById("_af_notice_body").value || "").trim();
            var dismiss = (document.getElementById("_af_notice_dismiss").value || "OK").trim();
            if (!title) { _toast("Title required", "err"); return false; }
            if (!body)  { _toast("Message body required", "err"); return false; }
            var audMode = (document.querySelector('input[name="_af_notice_aud"]:checked') || {}).value
              || (hasTarget ? "this" : "all");
            var targetEmail = hasTarget ? id.email : null;
            var audFields = _buildAudienceFields(audMode, targetEmail);
            var audLabel = hasTarget
              ? _audienceLabel(audMode, _displayName(userId))
              : "everyone";
            var audIdSuffix = hasTarget
              ? _audienceIdSuffix(audMode, userId)
              : "all";
            var reason = (document.getElementById("_af_notice_reason").value || "").trim();

            // Convert plain-text newlines to <br> if no HTML tags detected.
            // Heuristic: if body has any `<` char, treat as HTML; otherwise
            // wrap in <p> and convert newlines. Keeps the simple case
            // simple while letting power users hand-craft markup.
            var html = (body.indexOf("<") === -1)
              ? "<p>" + _esc(body).replace(/\n/g, "<br>") + "</p>"
              : body;

            var overrideId = "fleet-notice-" + audIdSuffix + "-" + Date.now();
            var entry = Object.assign({
              id: overrideId,
              actions: [{
                type: "notice",
                title: title,
                html: html,
                dismissLabel: dismiss || "OK",
              }],
              pushedAt: new Date().toISOString(),
              pushedBy: (_userIdentity && _userIdentity.email) || "unknown",
            }, audFields);
            if (reason) entry.note = reason;

            _toast("⏳ Sending notice…", "info");
            _pushOverride(entry).then(function () {
              _toast("✅ Notice queued for " + audLabel, "ok");
              _renderDashboard();
            }).catch(function (err) {
              _toast("Send failed: " + (err && err.message || "unknown"), "err");
            });

            if (overlay && overlay.parentNode) overlay.parentNode.removeChild(overlay);
          },
        },
      ],
    });
  }

  // ── Dialog: survey push (Tier-2 admin-pushed survey) ───────────────
  // 2026-05-25: composes a `present_survey` action override which the
  // target's eli-admin dispatches into survey_tester's survey.push
  // channel. Survey lands in the user's Pending list on their next
  // override poll (or boot). Same audience picker as notice/setting
  // pushes — pass userId for targeted or null for broadcast.
  //
  // Requires the target to have survey_tester installed. If they don't,
  // present_survey rejects → applied-marker not written → override
  // re-fires next poll once the tool is installed. Graceful degrade.
  function _showSurveyPusher(userId) {
    if (typeof showEliDialog !== "function") return;
    var id = userId ? _identityFor(userId) : null;
    if (userId && (!id || !id.email)) {
      _toast("Identify user first (need their email)", "err");
      return;
    }
    var hasTarget = !!id;
    var headline = hasTarget
      ? "Push survey to " + _esc(_displayName(userId)) + " (or broader audience)"
      : "Push survey to fleet";

    var audienceHtml = hasTarget
      ? _audienceRadioHtml("_af_survey_aud")
      : '<label class="_eli3_af_radio"><input type="radio" name="_af_survey_aud" value="all" checked> ' +
          '<b>Everyone</b> — broadcast to entire fleet</label>';

    // Default JSON template — same shape as survey_tester's DEMO_SURVEY,
    // simplified to 2 questions so the dialog stays readable.
    var defaultSpec = {
      title: "Quick check on ELI",
      description: "Two short questions — under 30 seconds.",
      questions: [
        { id: "q1", type: "rating", label: "How likely are you to recommend ELI?", min: 0, max: 10, required: true,
          hint: "0 = not at all, 10 = absolutely" },
        { id: "q2", type: "text", label: "Anything else?", placeholder: "Optional", multiline: true, required: false },
      ],
    };

    var bodyHtml =
      '<div class="_eli3_af_form">' +
        (hasTarget
          ? '<div class="_eli3_af_form_row">' +
              '<label>User</label>' +
              '<div class="_eli3_af_form_val_static">' + _esc(_displayName(userId)) + ' (' + _esc(id.email) + ')</div>' +
            '</div>'
          : '') +
        '<div class="_eli3_af_form_row">' +
          '<label>Survey JSON <span class="_eli3_af_req">*</span></label>' +
          '<textarea id="_af_survey_spec" rows="14" spellcheck="false" ' +
            'style="font:12px/1.45 \'SF Mono\',\'Consolas\',monospace; white-space:pre;">' +
            _esc(JSON.stringify(defaultSpec, null, 2)) +
          '</textarea>' +
          '<div style="margin-top:4px;display:flex;gap:6px;">' +
            '<button type="button" data-tpl="demo" class="_eli3_af_btn _eli3_af_btn_sm">Reset template</button>' +
            '<button type="button" data-tpl="validate" class="_eli3_af_btn _eli3_af_btn_sm">Validate</button>' +
            '<span id="_af_survey_validate" style="font-size:11px;color:#475569;align-self:center;"></span>' +
          '</div>' +
        '</div>' +
        '<div class="_eli3_af_form_row">' +
          '<label>Audience</label>' +
          '<div>' + audienceHtml + '</div>' +
        '</div>' +
        '<div class="_eli3_af_form_row">' +
          '<label>Reason (note)</label>' +
          '<input type="text" id="_af_survey_reason" placeholder="(optional admin note — NOT shown to recipients)">' +
        '</div>' +
        '<div style="margin-top:8px;padding:6px 8px;background:#f1f5f9;border-radius:4px;font-size:11px;color:#475569;">' +
          '💡 Recipients need <b>survey_tester</b> installed. Survey lands in their Pending list on next override poll (or boot). ' +
          'Question types: <code>rating</code> (min/max), <code>multiselect</code> (options[]), ' +
          '<code>single</code> (options[]), <code>text</code> (placeholder, multiline). ' +
          'Each question needs <code>{id, type, label, required?}</code>.' +
        '</div>' +
      '</div>';

    showEliDialog({
      variant: "neutral",
      size: "wide",
      icon: "📋",
      title: headline,
      body: bodyHtml,
      onMount: function (overlay) {
        var ta = overlay.querySelector("#_af_survey_spec");
        if (ta) setTimeout(function () { ta.focus(); }, 50);
        // Template / validate buttons
        var tplBtns = overlay.querySelectorAll("[data-tpl]");
        Array.prototype.forEach.call(tplBtns, function (b) {
          b.onclick = function () {
            var kind = b.getAttribute("data-tpl");
            var info = overlay.querySelector("#_af_survey_validate");
            if (kind === "demo") {
              ta.value = JSON.stringify(defaultSpec, null, 2);
              if (info) { info.textContent = ""; info.style.color = "#475569"; }
            } else if (kind === "validate") {
              var raw = ta.value.trim();
              if (!raw) { if (info) { info.textContent = "Empty."; info.style.color = "#b91c1c"; } return; }
              try {
                var parsed = JSON.parse(raw);
                if (!parsed || !Array.isArray(parsed.questions) || !parsed.questions.length) {
                  if (info) { info.textContent = "✗ Needs questions[] array"; info.style.color = "#b91c1c"; }
                } else {
                  if (info) { info.textContent = "✓ " + parsed.questions.length + " question(s), valid JSON"; info.style.color = "#15803d"; }
                }
              } catch (e) {
                if (info) { info.textContent = "✗ " + e.message; info.style.color = "#b91c1c"; }
              }
            }
          };
        });
      },
      buttons: [
        {
          label: "Cancel",
          cls: "btn-secondary",
          onclick: function (e, ov) { if (ov && ov.parentNode) ov.parentNode.removeChild(ov); },
        },
        {
          label: "Push",
          cls: "btn-action btn-primary",
          onclick: function (e, overlay) {
            var raw = (document.getElementById("_af_survey_spec").value || "").trim();
            if (!raw) { _toast("Survey JSON required", "err"); return false; }
            var spec;
            try { spec = JSON.parse(raw); }
            catch (e2) { _toast("Invalid JSON: " + e2.message, "err"); return false; }
            if (!spec || !Array.isArray(spec.questions) || !spec.questions.length) {
              _toast("Spec needs a questions[] array", "err"); return false;
            }
            if (!spec.id) spec.id = "survey-" + Date.now().toString(36) + "-" + Math.random().toString(36).slice(2, 6);

            var audMode = (document.querySelector('input[name="_af_survey_aud"]:checked') || {}).value
              || (hasTarget ? "this" : "all");
            var targetEmail = hasTarget ? id.email : null;
            var audFields = _buildAudienceFields(audMode, targetEmail);
            var audLabel = hasTarget
              ? _audienceLabel(audMode, _displayName(userId))
              : "everyone";
            var audIdSuffix = hasTarget
              ? _audienceIdSuffix(audMode, userId)
              : "all";
            var reason = (document.getElementById("_af_survey_reason").value || "").trim();

            var overrideId = "fleet-survey-" + audIdSuffix + "-" + Date.now();
            var entry = Object.assign({
              id: overrideId,
              actions: [{
                type: "present_survey",
                spec: spec,
              }],
              pushedAt: new Date().toISOString(),
              pushedBy: (_userIdentity && _userIdentity.email) || "unknown",
            }, audFields);
            if (reason) entry.note = reason;

            _toast("⏳ Pushing survey…", "info");
            _pushOverride(entry).then(function () {
              _toast("✅ Survey queued for " + audLabel, "ok");
              _renderDashboard();
            }).catch(function (err) {
              _toast("Push failed: " + (err && err.message || "unknown"), "err");
            });

            if (overlay && overlay.parentNode) overlay.parentNode.removeChild(overlay);
          },
        },
      ],
    });
  }

  // ── Dialog: dashboard layout push (2026-05-25) ─────────────────────
  // Lets admin define the exact pinned-apps list for a target audience.
  // Reads admin's own STORE_JSON_TOOLS to enumerate pinnable tiles (any
  // installed tool that's NOT hidden), reads target's telemetry-reported
  // dashboardApps for drift indicators (keep/adds/removes per row).
  // Default-checked = catalog defaults (catalog.default === true).
  //
  // Pushes either set_dashboard_pins (replaces wholesale) or
  // reset_dashboard_to_defaults (clears the key). The reset variant
  // appears as a quick-action when the admin un-checks all custom
  // selections — the modal auto-detects that the resulting list matches
  // catalog defaults and offers to push the lighter-weight reset action
  // instead.
  function _showDashboardLayoutPusher(userId) {
    if (typeof showEliDialog !== "function") return;
    var id = userId ? _identityFor(userId) : null;
    if (userId && (!id || !id.email)) {
      _toast("Identify user first (need their email)", "err");
      return;
    }
    var hasTarget = !!id;
    var headline = hasTarget
      ? "Dashboard layout for " + _esc(_displayName(userId))
      : "Push dashboard layout to fleet";

    // Step 1: enumerate every pinnable tile from admin's own IDB bundles.
    // Filter out hidden tools (hidden catalog entries don't render on the
    // tile grid — they surface via footer pills / chat bar / etc.).
    if (!window.eli || !window.eli.tools || typeof window.eli.tools.list !== "function") {
      _toast("Kernel tools API missing", "err"); return;
    }
    window.eli.tools.list().then(function (bundles) {
      var tiles = (bundles || []).filter(function (b) {
        if (!b || b.disabled) return false;
        if (String(b.id || "").charAt(0) === "_") return false;  // skip kernel/metadata rows
        var cat = b.catalog || {};
        if (cat.hidden) return false;
        if (!cat.id) return false;
        return true;
      }).map(function (b) {
        var cat = b.catalog || {};
        return {
          catalogId: cat.id,
          toolId: b.id,
          icon: cat.icon || "🛠️",
          title: cat.title || b.label || b.id,
          category: cat.category || "Tools",
          isDefault: !!cat.default,
          isCore: !!cat.core,
        };
      }).sort(function (a, b) {
        // Defaults first, then alphabetical
        if (a.isDefault !== b.isDefault) return a.isDefault ? -1 : 1;
        return String(a.title).localeCompare(b.title);
      });

      // Step 2: figure out what's currently pinned (per-user from telemetry).
      // For broadcast, summarize across all known users.
      var currentlyPinnedSet = {};            // single user: catalogId → true
      var fleetPinHisto = {};                 // broadcast: catalogId → count
      var fleetPinUserCount = 0;
      var freshnessNote = "";
      if (hasTarget) {
        var fleet = _telemetryByUserId[userId] || null;
        if (fleet && Array.isArray(fleet.dashboardApps)) {
          fleet.dashboardApps.forEach(function (cid) { currentlyPinnedSet[cid] = true; });
          freshnessNote = " (as of last telemetry push)";
        } else {
          freshnessNote = " (no telemetry yet — pin state unknown)";
        }
      } else {
        var users = _allUsers();
        users.forEach(function (uid) {
          var f = _telemetryByUserId[uid];
          if (f && Array.isArray(f.dashboardApps)) {
            fleetPinUserCount++;
            f.dashboardApps.forEach(function (cid) {
              fleetPinHisto[cid] = (fleetPinHisto[cid] || 0) + 1;
            });
          }
        });
      }

      // Step 3: render the modal.
      var audienceHtml = hasTarget
        ? _audienceRadioHtml("_af_layout_aud")
        : '<label class="_eli3_af_radio"><input type="radio" name="_af_layout_aud" value="all" checked> ' +
            '<b>Everyone</b> — push to entire fleet</label>';

      var tilesHtml = tiles.map(function (t) {
        var isCurrentlyPinned = hasTarget
          ? !!currentlyPinnedSet[t.catalogId]
          : (fleetPinHisto[t.catalogId] || 0) > 0;
        var defaultChecked = t.isDefault;
        // Drift annotation (per-user only — broadcast uses histogram instead).
        var driftHtml = "";
        if (hasTarget) {
          if (defaultChecked && isCurrentlyPinned) {
            driftHtml = '<span style="color:#64748b;font-size:11px;margin-left:auto;">⚠ keep</span>';
          } else if (defaultChecked && !isCurrentlyPinned) {
            driftHtml = '<span style="color:#15803d;font-size:11px;font-weight:600;margin-left:auto;">✚ adds</span>';
          } else if (!defaultChecked && isCurrentlyPinned) {
            driftHtml = '<span style="color:#b91c1c;font-size:11px;font-weight:600;margin-left:auto;">✖ removes</span>';
          } else {
            driftHtml = '<span style="color:#cbd5e1;font-size:11px;margin-left:auto;">·</span>';
          }
        } else if (fleetPinUserCount > 0) {
          var n = fleetPinHisto[t.catalogId] || 0;
          driftHtml = '<span style="color:#64748b;font-size:11px;margin-left:auto;">' + n + '/' + fleetPinUserCount + '</span>';
        }
        var tags = [];
        if (t.isCore) tags.push('<span style="background:#fef3c7;color:#92400e;font-size:9px;font-weight:700;padding:1px 5px;border-radius:3px;letter-spacing:0.5px;">CORE</span>');
        if (t.isDefault) tags.push('<span style="background:#dbeafe;color:#1e40af;font-size:9px;font-weight:700;padding:1px 5px;border-radius:3px;letter-spacing:0.5px;">DEFAULT</span>');
        var tagsHtml = tags.length ? '<span style="margin-left:6px;display:inline-flex;gap:3px;">' + tags.join("") + '</span>' : '';
        return (
          '<label class="_eli3_af_layout_row" data-cat-id="' + _esc(t.catalogId) + '"' +
            ' style="display:flex;align-items:center;gap:8px;padding:7px 10px;cursor:pointer;border-radius:5px;font:13px/1.3 Inter,sans-serif;">' +
            '<input type="checkbox" name="_af_layout_pins" value="' + _esc(t.catalogId) + '"' + (defaultChecked ? " checked" : "") + ' style="cursor:pointer;flex-shrink:0;">' +
            '<span style="font-size:14px;flex-shrink:0;width:18px;text-align:center;">' + _esc(t.icon) + '</span>' +
            '<span style="flex:1;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;">' + _esc(t.title) + tagsHtml + '</span>' +
            driftHtml +
          '</label>'
        );
      }).join("");

      var infoStripe = hasTarget
        ? 'Currently pinned' + _esc(freshnessNote) + ': <b>' + Object.keys(currentlyPinnedSet).length + ' tile(s)</b>. ' +
          'Pre-filled checkboxes = your catalog defaults. Check/uncheck to define the new layout.'
        : 'Pin counts shown per tile (X/' + fleetPinUserCount + ' users currently pinning). ' +
          'Pre-filled checkboxes = catalog defaults. Push replaces every recipient\'s pinned list.';

      var bodyHtml =
        '<div class="_eli3_af_form">' +
          (hasTarget
            ? '<div class="_eli3_af_form_row">' +
                '<label>User</label>' +
                '<div class="_eli3_af_form_val_static">' + _esc(_displayName(userId)) + ' (' + _esc(id.email) + ')</div>' +
              '</div>'
            : '') +
          '<div style="padding:8px 10px;background:#f1f5f9;border-radius:5px;font-size:11.5px;color:#475569;margin-bottom:10px;">' +
            infoStripe +
          '</div>' +
          '<div class="_eli3_af_form_row">' +
            '<label>Pinned tiles</label>' +
            '<div style="max-height:340px;overflow-y:auto;border:1px solid #e2e8f0;border-radius:6px;padding:4px;">' +
              tilesHtml +
            '</div>' +
            '<div style="margin-top:4px;display:flex;gap:6px;">' +
              '<button type="button" data-act="layout-check-defaults" class="_eli3_af_btn _eli3_af_btn_sm">Reset to defaults</button>' +
              '<button type="button" data-act="layout-check-all" class="_eli3_af_btn _eli3_af_btn_sm">Check all</button>' +
              '<button type="button" data-act="layout-check-none" class="_eli3_af_btn _eli3_af_btn_sm">Check none</button>' +
            '</div>' +
          '</div>' +
          '<div class="_eli3_af_form_row">' +
            '<label>Audience</label>' +
            '<div>' + audienceHtml + '</div>' +
          '</div>' +
          '<div class="_eli3_af_form_row">' +
            '<label>Reason (note)</label>' +
            '<input type="text" id="_af_layout_reason" placeholder="(optional admin note — NOT shown to recipients)">' +
          '</div>' +
          '<div style="margin-top:8px;padding:6px 8px;background:#fef3c7;border-left:3px solid #d97706;border-radius:4px;font-size:11px;color:#78350f;">' +
            '💡 If your pin list matches catalog defaults exactly, the push uses the lighter-weight ' +
            '<code>reset_dashboard_to_defaults</code> action. Otherwise it uses ' +
            '<code>set_dashboard_pins</code> with the explicit list. Recipients see the change on their next ' +
            'override poll (or boot).' +
          '</div>' +
        '</div>';

      showEliDialog({
        variant: "neutral",
        size: "wide",
        icon: "🎛",
        title: headline,
        body: bodyHtml,
        onMount: function (overlay) {
          // Wire helper buttons (check-defaults / check-all / check-none)
          var checks = function () { return overlay.querySelectorAll("input[name='_af_layout_pins']"); };
          var btnDefaults = overlay.querySelector("[data-act='layout-check-defaults']");
          var btnAll = overlay.querySelector("[data-act='layout-check-all']");
          var btnNone = overlay.querySelector("[data-act='layout-check-none']");
          if (btnDefaults) btnDefaults.onclick = function () {
            var cbs = checks();
            cbs.forEach(function (cb) {
              var tile = tiles.find(function (t) { return t.catalogId === cb.value; });
              cb.checked = !!(tile && tile.isDefault);
            });
          };
          if (btnAll) btnAll.onclick = function () { checks().forEach(function (cb) { cb.checked = true; }); };
          if (btnNone) btnNone.onclick = function () { checks().forEach(function (cb) { cb.checked = false; }); };
        },
        buttons: [
          { label: "Cancel", cls: "btn-secondary",
            onclick: function (e, ov) { if (ov && ov.parentNode) ov.parentNode.removeChild(ov); } },
          { label: "Push", cls: "btn-action btn-primary",
            onclick: function (e, overlay) {
              var checked = [];
              overlay.querySelectorAll("input[name='_af_layout_pins']:checked").forEach(function (cb) {
                checked.push(cb.value);
              });
              var audMode = (document.querySelector('input[name="_af_layout_aud"]:checked') || {}).value
                || (hasTarget ? "this" : "all");
              var targetEmail = hasTarget ? id.email : null;
              var audFields = _buildAudienceFields(audMode, targetEmail);
              var audLabel = hasTarget ? _audienceLabel(audMode, _displayName(userId)) : "everyone";
              var audIdSuffix = hasTarget ? _audienceIdSuffix(audMode, userId) : "all";
              var reason = (document.getElementById("_af_layout_reason").value || "").trim();

              // Detect: does the chosen set match catalog defaults exactly?
              // If so, use the lighter reset action.
              var defaultSet = {};
              tiles.forEach(function (t) { if (t.isDefault) defaultSet[t.catalogId] = true; });
              var checkedSet = {}; checked.forEach(function (c) { checkedSet[c] = true; });
              var matchesDefaults = Object.keys(defaultSet).length === checked.length &&
                Object.keys(defaultSet).every(function (k) { return checkedSet[k]; });
              var action = matchesDefaults
                ? { type: "reset_dashboard_to_defaults" }
                : { type: "set_dashboard_pins", pins: checked };

              var overrideId = "fleet-layout-" + audIdSuffix + "-" + Date.now();
              var entry = Object.assign({
                id: overrideId,
                actions: [action],
                pushedAt: new Date().toISOString(),
                pushedBy: (_userIdentity && _userIdentity.email) || "unknown",
              }, audFields);
              if (reason) entry.note = reason;

              _toast("⏳ Pushing layout…", "info");
              _pushOverride(entry).then(function () {
                _toast("✅ Layout queued for " + audLabel + " (" +
                  (matchesDefaults ? "reset to defaults" : checked.length + " tile" + (checked.length === 1 ? "" : "s")) + ")", "ok");
                _renderDashboard();
              }).catch(function (err) {
                _toast("Push failed: " + (err && err.message || "unknown"), "err");
              });

              if (overlay && overlay.parentNode) overlay.parentNode.removeChild(overlay);
            } },
        ],
      });
    }).catch(function (err) {
      _toast("Failed to list tools: " + (err && err.message || "unknown"), "err");
    });
  }

  // ── Dialog: data library push (force redownload / delete + audience) ──
