  // ── Revert a setting override ────────────────────────────────────
  // 2026-05-23c+: pushes a clear_setting_override for each set_setting /
  // set_setting_encrypted action in the source override, with the SAME
  // audience (so the inverse lands on the same set of users). After the
  // clear is queued, removes the original from admin-overrides.json so
  // it can never re-fire (e.g. via resetApplied + repoll).
  //
  // Two failure modes worth knowing:
  //   - Original used force:"reset" → wrote to user pref; clear_setting_
  //     override only strips admin layers, can't reach user pref. UI
  //     hides the Revert button for those rows; this function defends
  //     against being called anyway.
  //   - Target on stale kernel — clear_setting_override still works
  //     (it's been in eli-admin since Phase 7b), so no kernel-version
  //     guard needed.
  function _revertOverride(overrideId) {
    var ov = (_adminOverrides && _adminOverrides.overrides || []).find(function (o) {
      return o.id === overrideId;
    });
    if (!ov) {
      _toast("Override not found in admin-overrides.json (already removed?)", "err");
      return;
    }
    var clearable = (ov.actions || []).filter(function (a) {
      return (a.type === "set_setting" || a.type === "set_setting_encrypted")
        && a.force !== "reset";
    });
    if (!clearable.length) {
      _toast("Nothing to revert — no force/soft setting actions in this override", "warn");
      return;
    }
    var clearActions = clearable.map(function (a) {
      return { type: "clear_setting_override", key: a.key };
    });
    // Inherit audience exactly so the clear reaches the same users.
    var clearOverride = {
      id: "fleet-revert-" + ov.id + "-" + Date.now(),
      actions: clearActions,
      pushedAt: new Date().toISOString(),
      pushedBy: (_userIdentity && _userIdentity.email) || "unknown",
      note: "Revert of " + ov.id,
    };
    if (ov.audience) clearOverride.audience = ov.audience.slice();
    if (ov.audienceEmails) clearOverride.audienceEmails = ov.audienceEmails.slice();
    if (ov.audienceEmailExcludes) clearOverride.audienceEmailExcludes = ov.audienceEmailExcludes.slice();

    _toast("⏳ Pushing revert…", "info");
    _pushOverride(clearOverride)
      .then(function () { return _removeOverride(overrideId); })
      .then(function () {
        _toast("✅ Revert queued + original removed from CDN", "ok");
        _renderDashboard();
      })
      .catch(function (err) {
        _toast("Revert failed: " + (err && err.message || "unknown"), "err");
      });
  }

