  // ── Tool uninstall (manifest audience removal + force_redownload) ──
  // True uninstall is a TWO-STEP operation:
  //   1. Edit tools-manifest-v3.json — remove user's email from the tool's
  //      audienceEmails. Without this, the user's next sync auto-installs
  //      the tool back (manifest still lists them in audience).
  //   2. Push a force_redownload_tool override targeted at this user. That
  //      action calls eli.tools.uninstall on their machine → removes from
  //      IDB → tile vanishes from their dashboard.
  // Result: tool gone, won't auto-reinstall. To re-grant access later,
  // add the email back to the manifest audience and run Force re-install.
  // 2026-05-23 (Phase 2): tool-overrides audit. Walks every active
  // override, picks the audience_grant_user / audience_revoke_user /
  // audience_clear_user_override actions, folds them per toolId (later
  // overrides win, same precedence as kernel's _userToolOverride hydration),
  // and resolves each target audience back to a user via _lookup.
  //
  // Result shape:
  //   { [toolId]: [{ userId, displayName, email, userIdHash, mode, overrideId, pushedAt }] }
  //
  // userId may be null when the override targeted a user we don't have
  // an identity record for (e.g., audienceEmails for someone not in
  // _lookup). In that case displayName falls back to the email or UUID.
  function _toolOverridesAudit() {
    var all = (_adminOverrides && _adminOverrides.overrides) || [];
    // 1) Resolve each override to (toolId, userKey, mode, override metadata).
    //    userKey is the canonical id for grouping — UUID if available,
    //    else email lowercase, else "broadcast:all" sentinel.
    var emailToUserId = {};
    Object.keys(_lookup || {}).forEach(function (uid) {
      var rec = _lookup[uid];
      if (rec && rec.email) emailToUserId[String(rec.email).toLowerCase()] = uid;
    });
    var entries = [];
    all.slice().sort(function (a, b) {
      return new Date(a.pushedAt || 0) - new Date(b.pushedAt || 0);
    }).forEach(function (o) {
      if (!o || !Array.isArray(o.actions)) return;
      var modeActions = o.actions.filter(function (a) {
        return a && (a.type === "audience_grant_user" ||
                     a.type === "audience_revoke_user" ||
                     a.type === "audience_clear_user_override");
      });
      if (!modeActions.length) return;
      // Resolve audience to (userId, displayName, email) tuples.
      var targets = [];
      if (Array.isArray(o.audience) && o.audience.indexOf("all") !== -1) {
        targets.push({ userId: null, displayName: "Broadcast (all users)", email: null, kind: "broadcast" });
      }
      if (Array.isArray(o.audienceEmails)) {
        o.audienceEmails.forEach(function (em) {
          var emLc = String(em).toLowerCase();
          var uid = emailToUserId[emLc] || null;
          targets.push({
            userId: uid,
            displayName: uid ? _displayName(uid) : em,
            email: em,
            kind: "email",
          });
        });
      }
      if (Array.isArray(o.audienceUserIds)) {
        o.audienceUserIds.forEach(function (uid) {
          var rec = _lookup[uid];
          targets.push({
            userId: uid,
            displayName: rec ? _displayName(uid) : uid,
            email: rec && rec.email,
            kind: "userId",
          });
        });
      }
      modeActions.forEach(function (a) {
        targets.forEach(function (tg) {
          entries.push({
            toolId: a.toolId,
            mode: a.type === "audience_grant_user" ? "grant" :
                  a.type === "audience_revoke_user" ? "revoke" : "clear",
            target: tg,
            overrideId: o.id,
            pushedAt: o.pushedAt || null,
            pushedBy: o.pushedBy || null,
          });
        });
      });
    });
    // 2) Fold per toolId per target (later wins, "clear" deletes).
    var byTool = {};
    entries.forEach(function (e) {
      if (!e.toolId) return;
      byTool[e.toolId] = byTool[e.toolId] || {};
      var key = e.target.userId || e.target.email || "broadcast";
      if (e.mode === "clear") {
        delete byTool[e.toolId][key];
      } else {
        byTool[e.toolId][key] = e;
      }
    });
    // 3) Flatten into per-tool arrays, dropping empties.
    var result = {};
    Object.keys(byTool).forEach(function (tid) {
      var perUser = byTool[tid];
      var arr = Object.keys(perUser).map(function (k) { return perUser[k]; });
      arr.sort(function (a, b) {
        return String(a.target.displayName).localeCompare(String(b.target.displayName));
      });
      if (arr.length) result[tid] = arr;
    });
    return result;
  }

  // 2026-05-23 (Phase 2): override-only grant/revoke/clear. Single
  // admin-overrides.json push, no manifest mutation. Action types:
  //   audience_grant_user — installs + flags grant marker (audience-blind)
  //   audience_revoke_user — uninstalls + flags revoke marker
  //   audience_clear_user_override — removes the marker so audience rules apply again
  function _pushAudienceOverride(userId, toolId, actionType) {
    var id = _identityFor(userId);
    if (!id || (!id.email && !id.userId)) {
      _toast("Identify user first (need email or UUID for audience targeting)", "err");
      return;
    }
    if (!toolId) { _toast("Tool id missing", "err"); return; }
    var verb = actionType === "audience_grant_user" ? "grant" :
               actionType === "audience_revoke_user" ? "revoke" : "clear-override";
    var icon = actionType === "audience_grant_user" ? "🔓" :
               actionType === "audience_revoke_user" ? "🚫" : "↩";
    _toast("⏳ " + icon + " " + verb + " " + toolId + "…", "info");
    var overrideId = "fleet-" + verb + "-" + toolId + "-" + userId + "-" + Date.now();
    var entry = {
      id: overrideId,
      // Prefer UUID targeting — stable across email churn. Fall back to
      // email if UUID isn't known for this user yet.
      actions: [{ type: actionType, toolId: toolId }],
      pushedAt: new Date().toISOString(),
      pushedBy: (_userIdentity && _userIdentity.email) || "unknown",
    };
    if (id.userId) entry.audienceUserIds = [id.userId];
    else entry.audienceEmails = [id.email];
    _pushOverride(entry).then(function () {
      _toast("✅ " + icon + " " + verb + " " + toolId + " for " + _displayName(userId), "ok");
      _renderDashboard();
    }).catch(function (err) {
      _toast(verb + " failed: " + err.message, "err");
    });
  }

