      audienceUserIdExcludes: Array.isArray(entry.audienceUserIdExcludes) ? entry.audienceUserIdExcludes.slice() : [],
    };
    var DIALOG_ID = "_eli3_af_aud_editor_" + Date.now();
    function _renderChips(field, items, color) {
