    var knownUserIds = Object.keys(_lookup || {});
    var presetHtml = '<div style="margin-bottom:14px;padding:8px;background:#f1f5f9;border-radius:4px;">' +
      '<div style="font-size:10px;color:#64748b;margin-bottom:6px;font-weight:700;">Quick presets:</div>' +
      '<button data-aud-preset="public" style="font-size:10px;padding:4px 8px;margin:0 4px 0 0;background:#dcfce7;color:#166534;border:1px solid #86efac;border-radius:4px;cursor:pointer;font-weight:700;">🌍 Public (all)</button>' +
      '<button data-aud-preset="me" style="font-size:10px;padding:4px 8px;margin:0 4px 0 0;background:#dbeafe;color:#1e40af;border:1px solid #93c5fd;border-radius:4px;cursor:pointer;font-weight:700;">👤 Just me</button>' +
      '<button data-aud-preset="clear" style="font-size:10px;padding:4px 8px;margin:0 4px 0 0;background:#fef3c7;color:#92400e;border:1px solid #fcd34d;border-radius:4px;cursor:pointer;font-weight:700;">⚠️ Clear all</button>' +
    '</div>';
    // 2026-05-23 (Phase 2): pre-build datalists for email/UUID/domain
    // inputs. HTML5 <datalist> works in Script Lab iframe — browser
    // renders the dropdown natively, no extra JS. Each option's value
    // is what gets added to chips; label is the resolved display name.
    var EMAILS_DL = DIALOG_ID + "_dl_emails";
    var UIDS_DL = DIALOG_ID + "_dl_uids";
    var DOMAINS_DL = DIALOG_ID + "_dl_domains";
    var emailOpts = "";
    var uidOpts = "";
    var domainSet = {};
    Object.keys(_lookup || {}).forEach(function (uid) {
      var r = _lookup[uid];
      if (!r) return;
      var nm = _displayName(uid);
      if (r.email) {
        emailOpts += '<option value="' + _esc(r.email) + '" label="' + _esc(nm) + '">' + _esc(nm) + '</option>';
        var atIdx = r.email.indexOf("@");
        if (atIdx !== -1) {
