      '<datalist id="' + DOMAINS_DL + '">' + domainOpts + '</datalist>';
    var PREVIEW_ID = DIALOG_ID + "_preview";
    var bodyHtml =
      datalistHtml +
      '<div style="font-size:11px;color:#475569;margin-bottom:10px;">' +
        'Editing <code>' + _esc(toolId) + '</code>. Changes are committed to ' +
        '<code>tools-manifest-v3.json</code> on Save. The next manifest poll ' +
        'on each user installation picks up the new audience.' +
      '</div>' +
      presetHtml +
      _renderSection("audience", "Tags / groups (audience)",
        'Include "all" for public broadcast. Or list specific group/tag strings (matches user.group or user.tags).',
        null, DIALOG_ID + "_inp_audience", '"all", "internal", etc.', "text") +
      _renderSection("audienceEmails", "Emails (audienceEmails)",
        'Per-email allowlist. User matches if their email exactly equals (case-insensitive). Autocomplete from identity lookup.',
        null, DIALOG_ID + "_inp_audienceEmails", "user@example.com", "email", EMAILS_DL) +
      _renderSection("audienceEmailDomains", "Email domains (audienceEmailDomains)",
        'Per-domain allowlist. E.g. "@colpal.com" or "colpal.com".',
        null, DIALOG_ID + "_inp_audienceEmailDomains", "@colpal.com", "text", DOMAINS_DL) +
      _renderSection("audienceUserIds", "User IDs (audienceUserIds)",
        'Per-UUID allowlist. Stable across email churn. E.g. "AN-ioimnwgd". Autocomplete shows resolved names.',
        null, DIALOG_ID + "_inp_audienceUserIds", "AN-xxxxxxx", "text", UIDS_DL) +
      _renderSection("audienceEmailExcludes", "Email excludes (audienceEmailExcludes)",
        'Negative filter — wins over positive matches above. Same as the "🗑 Uninstall" button push.',
        "danger", DIALOG_ID + "_inp_audienceEmailExcludes", "user@example.com", "email", EMAILS_DL) +
      _renderSection("audienceUserIdExcludes", "User ID excludes (audienceUserIdExcludes)",
        'UUID negative filter — wins over positive matches above.',
        "danger", DIALOG_ID + "_inp_audienceUserIdExcludes", "AN-xxxxxxx", "text", UIDS_DL) +
      '<div style="font-size:10px;color:#94a3b8;margin-top:8px;">' +
        'Empty everywhere → public. Excludes always win over positive matches.' +
      '</div>' +
      // 2026-05-23 (Phase 2): live preview footer. Recomputes on every
      // chip mutation. Shows count + first ~15 matched names from your
      // current fleet (lookup + telemetry).
      '<div id="' + PREVIEW_ID + '" style="margin-top:12px;padding:10px;background:#f8fafc;border:1px solid #cbd5e1;border-radius:4px;font-size:11px;">' +
        '<div style="font-weight:700;color:#334155;margin-bottom:4px;">📊 Live preview — who matches this audience right now</div>' +
        '<div class="_eli3_af_aud_preview_body" style="color:#64748b;">Computing…</div>' +
      '</div>';
    var overlay = showEliDialog({
      variant: "neutral", icon: "🎯",
