        audienceEmailDomains: state.audienceEmailDomains,
        audienceUserIds: state.audienceUserIds,
        audienceEmailExcludes: state.audienceEmailExcludes,
        audienceUserIdExcludes: state.audienceUserIdExcludes,
      };
      var matched = _fleetUsersForAudience(entry);
      if (!matched.length) {
        previewEl.innerHTML = '<span style="color:#b91c1c;">⚠ Matches 0 users in your fleet.</span> ' +
          '<span style="color:#64748b;font-size:10px;">(But new joiners or unidentified installs may still match — fleet only shows users you\'ve identified or who have pushed telemetry.)</span>';
        return;
      }
      var showLimit = 15;
      var head = matched.slice(0, showLimit).map(function (u) {
        return '<span style="display:inline-block;background:#dcfce7;color:#166534;padding:1px 6px;border-radius:3px;font-size:10px;font-weight:600;margin:1px;">' +
          _esc(u.displayName) +
        '</span>';
      }).join('');
      var more = matched.length > showLimit ? ' <span style="color:#64748b;font-size:10px;">+' + (matched.length - showLimit) + ' more</span>' : '';
      previewEl.innerHTML = '<span style="font-weight:700;color:#0f172a;">' + matched.length +
