      if (preset) {
        if (preset === "public") {
          state.audience = ["all"];
          state.audienceEmails = [];
          state.audienceEmailDomains = [];
          state.audienceUserIds = [];
        } else if (preset === "me") {
          var myEm = (_userIdentity && _userIdentity.email) || "";
          state.audience = [];
