  // 2026-05-23 (Phase 2): commit audience editor state to the manifest.
  // Fetches current manifest SHA, replaces the entry's audience fields
  // with the editor state (deleting empty arrays so the manifest stays
  // tidy), updates lastUpdated, and pushes. On success, refreshes the
  // local manifest cache and re-renders so the audience browser reflects
  // the change immediately.
  function _saveAudience(toolId, state) {
    _toast("⏳ Saving audience for " + toolId + "…", "info");
    return _ghGet("tools-manifest-v3.json").then(function (r) {
      if (!r) throw new Error("manifest not on CDN");
      var manifest;
      try { manifest = JSON.parse(_b64ToStr(r.content)); }
      catch (e) { throw new Error("manifest parse failed: " + e.message); }
      var entry = (manifest.tools || []).find(function (t) { return t && t.id === toolId; });
      if (!entry) throw new Error("tool " + toolId + " not in manifest");
      // Apply state — set or delete each field based on emptiness.
      ["audience", "audienceEmails", "audienceEmailDomains", "audienceUserIds",
       "audienceEmailExcludes", "audienceUserIdExcludes"].forEach(function (k) {
        if (state[k] && state[k].length) entry[k] = state[k];
        else if (entry.hasOwnProperty(k)) delete entry[k];
      });
      manifest.lastUpdated = new Date().toISOString();
      var json = JSON.stringify(manifest, null, 2);
      var msg = "admin_fleet: edit audience for " + toolId + " @ " +
        new Date().toISOString().replace("T", " ").replace(/\..*/, "");
      return _ghPut("tools-manifest-v3.json", json, msg, r.sha);
    }).then(function () {
      _toast("✅ Audience saved for " + toolId, "ok");
      return _fetchToolsManifest().then(function () { _renderDashboard(); return true; });
    }).catch(function (err) {
      _toast("Save failed: " + err.message, "err");
      return false;
    });
  }

  // 2026-05-23 (Phase 2): bulk push dialog — one override targets all
  // users (audience: ["all"]) or a comma-separated email list. Two modes:
  //   revoke    → audience_revoke_user (override-only, reversible via Clear)
  //   uninstall → force_redownload_tool (also optional: delete the tool
  //               entry from the manifest so it can't auto-reinstall)
  function _showBulkAudiencePusher(toolId, mode) {
    if (typeof showEliDialog !== "function") return;
    var isUninstall = mode === "uninstall";
    var title = isUninstall ? "Bulk Uninstall — " + toolId : "Bulk Revoke — " + toolId;
    var icon = isUninstall ? "🗑" : "🚫";
    var actionType = isUninstall ? "force_redownload_tool" : "audience_revoke_user";
    var verb = isUninstall ? "uninstall" : "revoke";
    var primaryLabel = isUninstall ? "Uninstall" : "Revoke";
    var INPUT_TARGET_ID = "_af_bulk_" + verb + "_target";
    var INPUT_LIST_ID = "_af_bulk_" + verb + "_list";
    var INPUT_DELETE_ID = "_af_bulk_" + verb + "_delete_manifest";
    // Each path has different semantics — explain explicitly so admin
    // picks intentionally:
    //   Revoke    → reversible, per-user, no manifest edit. Uses the
    //               eli.tools._userToolOverrides marker. Tool stays in
    //               the manifest for everyone; the revoke marker blocks
    //               install on each targeted machine.
    //   Uninstall → permanent. Removes the tool ENTRY from the manifest
    //               entirely (no more audience match for anyone), then
    //               pushes force_redownload_tool to wipe existing copies.
    //               Targeted users can never auto-reinstall via manifest.
    //               Reversal requires re-publishing the tool bundle.
    //
    // The previous "Also remove from manifest" checkbox made manifest
    // removal optional, which silently made Uninstall a no-op (kernel
    // auto-reinstalls audience-matched tools on next poll). Removed.
    // Blurb is dynamic on the uninstall path — manifest mutation differs
    // between "all" (delete entire entry) and "list" (excludes append).
    // Hint switches via the live target radio; rendered with both states
    // visible so admin sees the consequence of either choice before
    // picking. Switches the visible/hidden block in the radio-change handler.
    var modeBlurb;
    if (isUninstall) {
      modeBlurb =
        '<div id="_af_bulk_unin_all" style="font-size:11px;color:#7f1d1d;background:#fef2f2;border:1px solid #fecaca;border-radius:4px;padding:8px;margin-bottom:10px;">' +
          '<b>⚠ Permanent deprecation (All users).</b> ' +
          'Deletes <code>' + _esc(toolId) + '</code> from <code>tools-manifest-v3.json</code> AND pushes ' +
          '<code>force_redownload_tool</code> to wipe existing copies. ' +
          'No one can install or update it after this. ' +
          'To restore: re-publish the tool bundle via the normal release pipeline.' +
        '</div>' +
        '<div id="_af_bulk_unin_list" style="font-size:11px;color:#7f1d1d;background:#fef2f2;border:1px solid #fecaca;border-radius:4px;padding:8px;margin-bottom:10px;display:none;">' +
          '<b>⚠ Permanent uninstall (specific users).</b> ' +
          'Adds each listed email to <code>audienceEmailExcludes</code> on <code>' + _esc(toolId) + '</code>\'s manifest entry AND pushes ' +
          '<code>force_redownload_tool</code> to wipe their existing copies. ' +
          'Tool stays in the manifest for everyone else. ' +
          'To restore for one user: click <code>↩️ Re-grant</code> on their card (removes from excludes).' +
        '</div>';
    } else {
      modeBlurb = '<div style="font-size:11px;color:#475569;margin-bottom:10px;">' +
        'Pushes <code>audience_revoke_user</code> override for <code>' + _esc(toolId) + '</code>. ' +
        'Each targeted install applies the revoke marker (kernel <code>matchesAudience</code> returns false from then on) and uninstalls the tool locally. ' +
        'No manifest edit. ' +
        '<b>Reversible:</b> click <code>↩ Clear</code> on the user\'s card or remove this override from the CDN.' +
      '</div>';
    }
    var bodyHtml =
      modeBlurb +
      '<div class="_eli3_af_form">' +
        '<div class="_eli3_af_form_row">' +
          '<label>Target</label>' +
          '<label class="_eli3_af_radio" style="display:block;margin-bottom:4px;">' +
            '<input type="radio" name="_af_bulk_target" value="all" checked> ' +
            '🌍 <b>All users</b> (broadcast — audience: ["all"])' +
          '</label>' +
          '<label class="_eli3_af_radio" style="display:block;margin-bottom:4px;">' +
            '<input type="radio" name="_af_bulk_target" value="list"> ' +
            '📧 <b>Specific emails</b> (comma- or newline-separated)' +
          '</label>' +
        '</div>' +
        '<div class="_eli3_af_form_row">' +
          '<label for="' + INPUT_LIST_ID + '">Email list (used when "Specific emails" selected)</label>' +
          '<textarea id="' + INPUT_LIST_ID + '" placeholder="andrew@..., jane@..., john@..." style="width:100%;min-height:60px;padding:6px;font-size:11px;font-family:Monaco,monospace;border:1px solid #cbd5e1;border-radius:4px;"></textarea>' +
          '<div style="font-size:10px;color:#94a3b8;margin-top:4px;">Newlines and commas both work. Whitespace-trimmed. Invalid-looking entries are skipped on save.</div>' +
        '</div>' +
      '</div>';
    var ov = showEliDialog({
      variant: isUninstall ? "warning" : "neutral",
      icon: icon, title: title, body: bodyHtml,
      buttons: [
        { label: "Cancel", cls: "btn-secondary",
          onclick: function (e, dlg) { if (dlg && dlg.parentNode) dlg.parentNode.removeChild(dlg); } },
        { label: primaryLabel, cls: "btn-action btn-primary",
          onclick: function (e, overlay) {
            var targetRadios = document.getElementsByName("_af_bulk_target");
            var targetMode = "all";
            for (var i = 0; i < targetRadios.length; i++) {
              if (targetRadios[i].checked) { targetMode = targetRadios[i].value; break; }
            }
            var emails = [];
            if (targetMode === "list") {
              var raw = (document.getElementById(INPUT_LIST_ID).value || "");
              emails = raw.split(/[,\n;]+/).map(function (s) { return s.trim(); })
                .filter(function (s) { return s && /.+@.+/.test(s); });
              if (!emails.length) {
                _toast("No valid emails in list", "err");
                return;
              }
            }
            if (overlay && overlay.parentNode) overlay.parentNode.removeChild(overlay);
            _pushBulkAudience(toolId, actionType, targetMode, emails, isUninstall);
          } },
      ],
    });
    // 2026-05-23: live-switch the uninstall consequence blurb when the
    // target radio changes (only relevant when isUninstall — the revoke
    // path has a single blurb that doesn't change).
    if (isUninstall && ov) {
      var blurbAll = ov.querySelector("#_af_bulk_unin_all");
      var blurbList = ov.querySelector("#_af_bulk_unin_list");
      ov.addEventListener("change", function (ev) {
        if (ev.target && ev.target.name === "_af_bulk_target") {
          var listMode = ev.target.value === "list";
          if (blurbAll) blurbAll.style.display = listMode ? "none" : "";
          if (blurbList) blurbList.style.display = listMode ? "" : "none";
        }
      });
    }
  }

  // 2026-05-23 (Phase 2): build + push the bulk action. Two manifest
  // mutations are possible — picked by (mode, target):
  //   revoke + (all|list)    → no manifest change (override-only path).
  //   uninstall + all        → delete tool ENTRY from manifest (deprecation).
  //   uninstall + list       → add each email to audienceEmailExcludes on
  //                            the tool's entry. Tool stays in manifest
  //                            for everyone else; listed users can't
  //                            reinstall. Symmetric with the per-user
  //                            "🗑 Uninstall (manifest)" button — same
  //                            mechanism, just batched.
  // Override always pushed; manifest mutation only when uninstalling.
  function _pushBulkAudience(toolId, actionType, targetMode, emails, isUninstall) {
    var verb = isUninstall ? "uninstall" : "revoke";
    var targetDesc = targetMode === "all"
      ? "all users"
      : emails.length + " email" + (emails.length === 1 ? "" : "s");
    _toast("⏳ Pushing bulk " + verb + " for " + toolId + " (" + targetDesc + ")…", "info");
    var overrideId = "fleet-bulk-" + verb + "-" + toolId + "-" + Date.now();
    var entry = {
      id: overrideId,
      actions: [{ type: actionType, toolId: toolId }],
      pushedAt: new Date().toISOString(),
      pushedBy: (_userIdentity && _userIdentity.email) || "unknown",
    };
    if (targetMode === "all") entry.audience = ["all"];
    else entry.audienceEmails = emails;
    var chain = _pushOverride(entry);
    if (isUninstall) {
      chain = chain.then(function () {
        var manifestVerb = targetMode === "all" ? "removing from manifest" : "adding to excludes";
        _toast("⏳ " + manifestVerb + "…", "info");
        return _ghGet("tools-manifest-v3.json").then(function (r) {
          if (!r) throw new Error("manifest not on CDN");
          var manifest;
          try { manifest = JSON.parse(_b64ToStr(r.content)); }
          catch (e) { throw new Error("manifest parse failed: " + e.message); }
          if (!Array.isArray(manifest.tools)) throw new Error("manifest has no tools array");
          var commitMsg;
          if (targetMode === "all") {
            // Deprecation — delete the entry entirely.
            var before = manifest.tools.length;
            manifest.tools = manifest.tools.filter(function (t) { return !(t && t.id === toolId); });
            if (manifest.tools.length === before) return; // already gone
            commitMsg = "admin_fleet: deprecate " + toolId +
              " (bulk uninstall + manifest removal) @ " +
              new Date().toISOString().replace("T", " ").replace(/\..*/, "");
          } else {
            // Per-list uninstall — append to audienceEmailExcludes.
            var toolEntry = manifest.tools.find(function (t) { return t && t.id === toolId; });
            if (!toolEntry) throw new Error("tool " + toolId + " not in manifest");
            if (!Array.isArray(toolEntry.audienceEmailExcludes)) toolEntry.audienceEmailExcludes = [];
            var existing = {};
            toolEntry.audienceEmailExcludes.forEach(function (em) {
              existing[String(em).toLowerCase()] = true;
            });
            var added = [];
            emails.forEach(function (em) {
              var emLc = String(em).toLowerCase();
              if (!existing[emLc]) {
                toolEntry.audienceEmailExcludes.push(em);
                existing[emLc] = true;
                added.push(em);
              }
            });
            // 2026-05-23: also remove the listed emails from
            // audienceEmails if present — keeps the manifest internally
            // consistent (no point in being on both the include AND
            // exclude list; excludes win anyway but admin shouldn't see
            // contradictory entries). Matches the single-user uninstaller
            // behavior at _showToolUninstaller.
            if (Array.isArray(toolEntry.audienceEmails) && toolEntry.audienceEmails.length) {
              var emailSet = {};
              emails.forEach(function (em) { emailSet[String(em).toLowerCase()] = true; });
              toolEntry.audienceEmails = toolEntry.audienceEmails.filter(function (em) {
                return !emailSet[String(em).toLowerCase()];
              });
            }
            if (!added.length) return; // all already excluded — nothing new to commit
            commitMsg = "admin_fleet: uninstall " + toolId + " for " + added.length +
              " user" + (added.length === 1 ? "" : "s") + " (bulk · added to excludes) @ " +
              new Date().toISOString().replace("T", " ").replace(/\..*/, "");
          }
          manifest.lastUpdated = new Date().toISOString();
          var json = JSON.stringify(manifest, null, 2);
          return _ghPut("tools-manifest-v3.json", json, commitMsg, r.sha);
        });
      });
    }
    chain.then(function () {
      _toast("✅ Bulk " + verb + " pushed for " + toolId, "ok");
      return _fetchToolsManifest().then(function () { _renderDashboard(); });
    }).catch(function (err) {
      _toast("Bulk " + verb + " failed: " + (err && err.message || err), "err");
    });
  }

  // 2026-05-23 (Phase 2): one-click public — set audience: ["all"] on
  // the tool's manifest entry. Skips other audience fields so any
  // existing emails/domains/UUIDs stay intact (admin can clean up via
  // the editor if they want). Single manifest commit.
  function _makeToolPublic(toolId) {
    if (!toolId) return;
    _toast("⏳ Making " + toolId + " public…", "info");
    _ghGet("tools-manifest-v3.json").then(function (r) {
      if (!r) throw new Error("manifest not on CDN");
      var manifest;
      try { manifest = JSON.parse(_b64ToStr(r.content)); }
      catch (e) { throw new Error("manifest parse failed: " + e.message); }
      var entry = (manifest.tools || []).find(function (t) { return t && t.id === toolId; });
      if (!entry) throw new Error("tool " + toolId + " not in manifest");
      entry.audience = ["all"];
      manifest.lastUpdated = new Date().toISOString();
      var json = JSON.stringify(manifest, null, 2);
      var msg = "admin_fleet: make " + toolId + " public (audience: ['all']) @ " +
        new Date().toISOString().replace("T", " ").replace(/\..*/, "");
      return _ghPut("tools-manifest-v3.json", json, msg, r.sha);
    }).then(function () {
      _toast("✅ " + toolId + " is now public", "ok");
      return _fetchToolsManifest().then(function () { _renderDashboard(); });
    }).catch(function (err) {
      _toast("Make public failed: " + (err && err.message || err), "err");
    });
  }

  function _showToolUninstaller(userId, toolId) {
    if (typeof showEliDialog !== "function") return;
    var id = _identityFor(userId);
    if (!id || !id.email) {
      _toast("Identify user first (need their email for manifest audience)", "err");
      return;
    }
    var bodyHtml =
      '<div class="_eli3_af_form">' +
        '<div class="_eli3_af_form_row">' +
          '<label>User</label>' +
          '<div class="_eli3_af_form_val_static">' + _esc(_displayName(userId)) + ' (' + _esc(id.email) + ')</div>' +
        '</div>' +
        '<div class="_eli3_af_form_row">' +
          '<label>Tool</label>' +
          '<div class="_eli3_af_form_val_static">' + _esc(toolId) + '</div>' +
        '</div>' +
        '<div class="_eli3_af_warn">⚠️ <b>Permanent uninstall.</b> ' +
        'Two steps: (1) remove user from the manifest audience so it won\'t re-install, ' +
        '(2) push force_redownload to clear from their IDB. ' +
        'To restore access later you\'ll have to manually add the user back to the manifest audience.</div>' +
        '<div class="_eli3_af_form_row">' +
          '<label>Reason</label>' +
          '<input type="text" id="_af_uninst_reason" placeholder="(optional admin note)">' +
        '</div>' +
      '</div>';
    showEliDialog({
      variant: "warning",
      icon: "🗑",
      title: "Uninstall tool from user",
      body: bodyHtml,
      buttons: [
        {
          label: "Cancel",
          cls: "btn-secondary",
          onclick: function (e, ov) {
            if (ov && ov.parentNode) ov.parentNode.removeChild(ov);
          },
        },
        {
          label: "Uninstall",
          cls: "btn-action btn-primary",
          onclick: function (e, overlay) {
            var reason = (document.getElementById("_af_uninst_reason").value || "").trim();
            _toast("⏳ Editing manifest…", "info");
            // Step 1: edit tools-manifest-v3.json to exclude this user.
            // Two paths depending on the tool's existing audience:
            //   • Has audienceEmails (per-email inclusion list) — remove
            //     the user's email from it.
            //   • Has audience: ["all"] OR no inclusion list — add the
            //     user's email to audienceEmailExcludes (negative filter,
            //     2026-05-23 kernel addition). Preserves "broadcast to
            //     everyone else" semantics.
            // Result either way: this user no longer matches the audience
            // on next sync → tool won't re-install after the override-
            // driven uninstall.
            _ghGet("tools-manifest-v3.json").then(function (r) {
              if (!r) throw new Error("tools-manifest-v3.json not found on CDN");
              var manifest;
              try { manifest = JSON.parse(_b64ToStr(r.content)); }
              catch (e) { throw new Error("manifest parse failed: " + e.message); }
              var sha = r.sha;
              var tools = manifest && manifest.tools;
              if (!Array.isArray(tools)) throw new Error("manifest has no tools array");
              var entry = tools.find(function (t) { return t && t.id === toolId; });
              if (!entry) throw new Error("tool " + toolId + " not in manifest");
              var emailLc = id.email.toLowerCase();
              var hasInclusion = Array.isArray(entry.audienceEmails) && entry.audienceEmails.length > 0;
              if (hasInclusion) {
                // Per-email audience — remove user's email from inclusion list.
                var before = entry.audienceEmails.length;
                entry.audienceEmails = entry.audienceEmails.filter(function (em) {
                  return String(em || "").toLowerCase() !== emailLc;
                });
                if (entry.audienceEmails.length === before) {
                  eli.log.event("tool", "admin_fleet_uninstall_not_in_audience", { toolId: toolId, email: id.email });
                }
              } else {
                // Broadcast audience (or no list) — add to exclude list.
                if (!Array.isArray(entry.audienceEmailExcludes)) entry.audienceEmailExcludes = [];
                var alreadyExcluded = entry.audienceEmailExcludes.some(function (em) {
                  return String(em || "").toLowerCase() === emailLc;
                });
                if (!alreadyExcluded) entry.audienceEmailExcludes.push(id.email);
              }
              manifest.lastUpdated = new Date().toISOString();
              var json = JSON.stringify(manifest, null, 2);
              var msg = "admin_fleet: uninstall " + toolId + " from " + id.email + " @ " +
                new Date().toISOString().replace("T", " ").replace(/\..*/, "");
              return _ghPut("tools-manifest-v3.json", json, msg, sha);
            }).then(function () {
              _toast("⏳ Pushing uninstall override…", "info");
              // Step 2: push force_redownload_tool override
              var overrideId = "fleet-uninstall-" + toolId + "-" + userId + "-" + Date.now();
              var entry = {
                id: overrideId,
                audienceEmails: [id.email],
                actions: [{ type: "force_redownload_tool", toolId: toolId }],
                pushedAt: new Date().toISOString(),
                pushedBy: (_userIdentity && _userIdentity.email) || "unknown",
              };
              if (reason) entry.note = reason;
              return _pushOverride(entry);
            }).then(function () {
              _toast("✅ Uninstalled " + toolId + " from " + _displayName(userId), "ok");
              // Refresh local manifest cache so the excluded-tools section
              // shows the new exclusion on next render.
              return _fetchToolsManifest().then(function () { _renderDashboard(); });
            }).catch(function (err) {
              _toast("Uninstall failed: " + err.message, "err");
            });
            if (overlay && overlay.parentNode) overlay.parentNode.removeChild(overlay);
          },
        },
      ],
    });
  }

  // ── Tool re-grant (remove user from audienceEmailExcludes) ──────
  // Inverse of uninstall. Removes the user's email from a tool's
  // audienceEmailExcludes so they match the audience on next sync.
  // Optionally pushes a force_redownload override so the tool installs
  // immediately rather than waiting for the next manifest poll.
  function _showToolRegrant(userId, toolId) {
    if (typeof showEliDialog !== "function") return;
    var id = _identityFor(userId);
    if (!id || !id.email) {
      _toast("Identify user first", "err");
      return;
    }
    var bodyHtml =
      '<div class="_eli3_af_form">' +
        '<div class="_eli3_af_form_row">' +
          '<label>User</label>' +
          '<div class="_eli3_af_form_val_static">' + _esc(_displayName(userId)) + ' (' + _esc(id.email) + ')</div>' +
        '</div>' +
        '<div class="_eli3_af_form_row">' +
          '<label>Tool</label>' +
          '<div class="_eli3_af_form_val_static">' + _esc(toolId) + '</div>' +
        '</div>' +
        '<div class="_eli3_af_form_val_static" style="margin-top:4px;color:#475569;font-size:11px;">' +
          'Removes this user from the tool\'s audienceEmailExcludes. ' +
          'They\'ll match the audience again on next sync and the tool will auto-install. ' +
          'Optionally trigger immediate install via force_redownload.' +
        '</div>' +
        '<div class="_eli3_af_form_row">' +
          '<label>Also trigger immediate install?</label>' +
          '<label class="_eli3_af_radio"><input type="checkbox" id="_af_regrant_install" checked> Yes (push force_redownload override)</label>' +
        '</div>' +
        '<div class="_eli3_af_form_row">' +
          '<label>Reason</label>' +
          '<input type="text" id="_af_regrant_reason" placeholder="(optional admin note)">' +
        '</div>' +
      '</div>';
    showEliDialog({
      variant: "neutral",
      icon: "↩️",
      title: "Re-grant tool access",
      body: bodyHtml,
      buttons: [
        {
          label: "Cancel",
          cls: "btn-secondary",
          onclick: function (e, ov) { if (ov && ov.parentNode) ov.parentNode.removeChild(ov); },
        },
        {
          label: "Re-grant",
          cls: "btn-action btn-primary",
          onclick: function (e, overlay) {
            var triggerInstall = !!document.getElementById("_af_regrant_install").checked;
            var reason = (document.getElementById("_af_regrant_reason").value || "").trim();
            _toast("⏳ Editing manifest…", "info");
            // Step 1: edit manifest to remove user from excludes
            _ghGet("tools-manifest-v3.json").then(function (r) {
              if (!r) throw new Error("manifest not on CDN");
              var manifest;
              try { manifest = JSON.parse(_b64ToStr(r.content)); }
              catch (e) { throw new Error("manifest parse failed: " + e.message); }
              var sha = r.sha;
              var entry = (manifest.tools || []).find(function (t) { return t && t.id === toolId; });
              if (!entry) throw new Error("tool " + toolId + " not in manifest");
              if (!Array.isArray(entry.audienceEmailExcludes)) entry.audienceEmailExcludes = [];
              var emailLc = id.email.toLowerCase();
              var before = entry.audienceEmailExcludes.length;
              entry.audienceEmailExcludes = entry.audienceEmailExcludes.filter(function (em) {
                return String(em || "").toLowerCase() !== emailLc;
              });
              if (entry.audienceEmailExcludes.length === before) {
                eli.log.event("tool", "admin_fleet_regrant_not_excluded", { toolId: toolId, email: id.email });
              }
              if (entry.audienceEmailExcludes.length === 0) delete entry.audienceEmailExcludes;
              manifest.lastUpdated = new Date().toISOString();
              var json = JSON.stringify(manifest, null, 2);
              var msg = "admin_fleet: re-grant " + toolId + " to " + id.email + " @ " +
                new Date().toISOString().replace("T", " ").replace(/\..*/, "");
              return _ghPut("tools-manifest-v3.json", json, msg, sha);
            }).then(function () {
              if (!triggerInstall) return;
              // Step 2 (optional): push force_redownload to trigger install
              _toast("⏳ Pushing install override…", "info");
              var overrideId = "fleet-regrant-" + toolId + "-" + userId + "-" + Date.now();
              var entry = {
                id: overrideId,
                audienceEmails: [id.email],
                actions: [{ type: "force_redownload_tool", toolId: toolId }],
                pushedAt: new Date().toISOString(),
                pushedBy: (_userIdentity && _userIdentity.email) || "unknown",
              };
              if (reason) entry.note = reason;
              return _pushOverride(entry);
            }).then(function () {
              _toast("✅ Re-granted " + toolId + " to " + _displayName(userId), "ok");
              return _fetchToolsManifest().then(function () { _renderDashboard(); });
            }).catch(function (err) {
              _toast("Re-grant failed: " + err.message, "err");
            });
            if (overlay && overlay.parentNode) overlay.parentNode.removeChild(overlay);
          },
        },
      ],
    });
  }

  // ── Dashboard rendering ──────────────────────────────────────────
  function _renderDashboard() {
    var out = window.eli.ui.claimOutput();
    out.classList.add("eli-view-enter");

    var unresolved = _unresolvedUsers();
    var resolved = _allUsers().filter(function (uid) { return _lookup[uid]; });
    // 2026-05-23c+: build per-email override list with full audience
    // matching (was email-only — broadcasts pushed via the Audience
    // picker would never appear on any card). Same precedence as kernel:
    // excludes win first, then audience:"all" broadcast, then per-email.
