        '<div class="_eli3_af_header_meta">' +
          _allUsers().length + ' users · ' +
          unresolved.length + ' unresolved · ' +
          (_adminOverrides && _adminOverrides.overrides ? _adminOverrides.overrides.length : 0) + ' active pushes' +
        '</div>' +
        '<div class="_eli3_af_header_actions">' +
          '<button class="_eli3_af_btn" id="_af_ai_models_mgr">🤖 AI Models Manager</button>' +
          '<button class="_eli3_af_btn" id="_af_push_layout">🎛 Dashboard Layout</button>' +
          '<button class="_eli3_af_btn" id="_af_push_survey">📋 Push Survey</button>' +
          '<button class="_eli3_af_btn" id="_af_broadcast">📢 Broadcast</button>' +
          '<button class="_eli3_af_btn" id="_af_refresh">🔄 Refresh</button>' +
          '<button class="_eli3_af_btn" id="_af_close">✕ Close</button>' +
        '</div>' +
      '</div>';

    var unresolvedHtml = "";
    if (unresolved.length) {
      unresolvedHtml = '<div class="_eli3_af_section">' +
        '<div class="_eli3_af_section_header">🆕 Unresolved users — click "Identify" to add them to your lookup</div>' +
        unresolved.map(_renderUserCard).join("") +
      '</div>';
    }

    var resolvedHtml = '<div class="_eli3_af_section">' +
      '<div class="_eli3_af_section_header">Resolved users (' + resolved.length + ')</div>' +
      (resolved.length ? resolved.map(_renderUserCard).join("") :
        '<div class="_eli3_af_empty">No users in the lookup table yet. Identify one above to get started.</div>') +
    '</div>';

    // 2026-05-23 (Phase 2): Tool Overrides Audit — pivot view of every
    // active audience_grant_user / audience_revoke_user across the fleet,
    // grouped per tool. Lets admin answer "who do I have legal_risks
    // revoked from?" in one place instead of scrolling per-user cards.
    var auditMap = _toolOverridesAudit();
    var auditToolIds = Object.keys(auditMap).sort();
    var auditTotalUsers = auditToolIds.reduce(function (sum, tid) {
      return sum + auditMap[tid].length;
    }, 0);
    var auditHtml = "";
    if (auditToolIds.length) {
      auditHtml = '<div class="_eli3_af_section">' +
        '<details class="_eli3_af_audit">' +
          '<summary class="_eli3_af_section_header">🔐 Tool Overrides Audit — ' +
            auditToolIds.length + ' tool' + (auditToolIds.length === 1 ? '' : 's') +
            ', ' + auditTotalUsers + ' user-target' + (auditTotalUsers === 1 ? '' : 's') +
            ' (click to expand)' +
          '</summary>' +
          '<div class="_eli3_af_audit_body">' +
            auditToolIds.map(function (tid) {
              var rows = auditMap[tid];
              var grantCount = rows.filter(function (r) { return r.mode === "grant"; }).length;
              var revokeCount = rows.filter(function (r) { return r.mode === "revoke"; }).length;
              var summary = [];
              if (grantCount) summary.push('<span style="color:#15803d;font-weight:700;">' + grantCount + ' granted</span>');
              if (revokeCount) summary.push('<span style="color:#b91c1c;font-weight:700;">' + revokeCount + ' revoked</span>');
              return '<details class="_eli3_af_audit_tool">' +
                '<summary class="_eli3_af_audit_tool_header">' +
                  '<code>' + _esc(tid) + '</code> · ' + summary.join(" · ") +
                '</summary>' +
                '<div class="_eli3_af_audit_users">' +
                  rows.map(function (r) {
                    var modeBadge = r.mode === "grant"
                      ? '<span style="font-size:9px;color:#15803d;font-weight:700;background:#dcfce7;padding:1px 5px;border-radius:3px;">🔓 GRANT</span>'
                      : '<span style="font-size:9px;color:#b91c1c;font-weight:700;background:#fee2e2;padding:1px 5px;border-radius:3px;">🚫 REVOKE</span>';
                    var pushedAt = r.pushedAt
                      ? '<span style="color:#94a3b8;font-size:10px;" title="' + _esc(r.pushedAt) + '">' +
                          _esc(String(r.pushedAt).slice(0, 10)) + '</span>'
                      : '';
                    // Broadcast targets (audience: ["all"]) can't be cleared
                    // per-user — the override applies to everyone. Clear
                    // means removing the override from CDN entirely, which
                    // the existing Remove-from-CDN button on the user-card
                    // overrides list already does.
                    var clearBtn = r.target.userId
                      ? '<button class="_eli3_af_btn_mini" data-act="audit-clear" data-uid="' + _esc(r.target.userId) + '" data-tool="' + _esc(tid) + '" title="Push audience_clear_user_override — user returns to audience-default state">↩ Clear</button>'
                      : (r.target.email
                          ? '<span style="font-size:10px;color:#94a3b8;" title="No user lookup record — clear via that user\'s card or the Remove-from-CDN button">unidentified</span>'
                          : '<span style="font-size:10px;color:#94a3b8;" title="Broadcast override — clear via Remove-from-CDN on any user\'s card">broadcast</span>');
                    var nameHtml = r.target.userId
                      ? _esc(r.target.displayName) +
                        (r.target.email ? ' <span style="color:#64748b;font-size:10px;">(' + _esc(r.target.email) + ')</span>' : '')
                      : _esc(r.target.displayName);
                    return '<div class="_eli3_af_audit_user_row">' +
                      modeBadge + ' ' +
                      '<span class="_eli3_af_audit_user_name">' + nameHtml + '</span> ' +
                      pushedAt + ' ' +
                      clearBtn +
                    '</div>';
                  }).join("") +
                '</div>' +
              '</details>';
            }).join("") +
          '</div>' +
        '</details>' +
      '</div>';
    }

    // 2026-05-23 (Phase 2): Tool Audience Browser — pivot view of the
    // manifest's audience gating per tool. Pairs with the Tool Overrides
    // Audit panel above ("Audience" = manifest's intended audience;
    // "Overrides" = per-user grant/revoke pushed via override). Each
    // tool row exposes an Edit Audience button that opens a chip-based
    // editor and commits the change via manifest mutation.
    var categories = _buildAudienceCategories();
    var catTotals = {
      public: categories.public.length,
      emails: categories.emails.length,
      domains: categories.domains.length,
      userIds: categories.userIds.length,
      tags: categories.tags.length,
      excluded: categories.excluded.length,
      open: categories.open.length,
    };
    var catTotal = catTotals.public + catTotals.emails + catTotals.domains +
                   catTotals.userIds + catTotals.tags + catTotals.open;
    function _editBtn(tid) {
      return '<button class="_eli3_af_btn_mini" data-act="tool-edit-audience" data-tool="' + _esc(tid) + '" title="Edit audience gates and push to manifest">✏️ Edit</button>' +
        '<button class="_eli3_af_btn_mini _eli3_af_btn_warn" data-act="tool-bulk-revoke" data-tool="' + _esc(tid) + '" title="Push audience_revoke_user to all users or a specific list. No manifest edit. Reversible via Clear.">🚫 Revoke…</button>' +
        '<button class="_eli3_af_btn_mini _eli3_af_btn_danger" data-act="tool-bulk-uninstall" data-tool="' + _esc(tid) + '" title="Push force_redownload_tool to all users or a specific list. Optionally remove from manifest entirely.">🗑 Uninstall…</button>';
    }
    // 2026-05-23: summaryExtras renders inline chips next to the tool
    // ID in the COLLAPSED header so admin sees the gated values at a
    // glance without expanding. Summary uses flex-wrap so long chip
    // lists wrap to a second row instead of overflowing.
    function _toolRow(tid, body, summaryExtras) {
      var entry = (_toolsManifest && (_toolsManifest.tools || []).find(function (t) { return t && t.id === tid; })) || null;
      var gapBadge = "";
      if (entry) {
        var gap = _toolInstallGap(entry);
        if (gap.matched > 0) {
          var color, bg, icon;
          if (gap.missing === 0) { color = "#15803d"; bg = "#dcfce7"; icon = "✓"; }
          else if (gap.missing <= 3) { color = "#a16207"; bg = "#fef3c7"; icon = "⚠"; }
          else { color = "#b91c1c"; bg = "#fee2e2"; icon = "✕"; }
          gapBadge = ' <span style="font-size:10px;color:' + color + ';background:' + bg + ';padding:1px 6px;border-radius:3px;font-weight:700;" title="' +
            gap.installed + ' of ' + gap.matched + ' audience-matched users have this tool installed (per latest telemetry). Missing = audience drift, install failures, or telemetry stale.">' +
            icon + ' ' + gap.installed + '/' + gap.matched +
          '</span>';
        }
      }
      return '<details class="_eli3_af_aud_tool">' +
        '<summary class="_eli3_af_aud_tool_header">' +
          '<div class="_eli3_af_aud_tool_summary_main">' +
            '<code>' + _esc(tid) + '</code> ' +
            gapBadge + ' ' +
            (summaryExtras || '') +
          '</div>' +
          _editBtn(tid) +
        '</summary>' +
        '<div class="_eli3_af_aud_tool_body">' + body + '</div>' +
      '</details>';
    }
    // 2026-05-23: compact chip for a single email in the summary row.
    // Smaller font + tighter padding than the expanded-body chip so a
    // tool with 4-5 emails still fits in one or two visible rows.
    // Resolved name (if known) is the chip face; raw email is the title.
    function _summaryEmailChip(em) {
      if (!em) return '';
      var emLc = String(em).toLowerCase();
      var matched = null;
      Object.keys(_lookup || {}).forEach(function (uid) {
        var rec = _lookup[uid];
        if (rec && rec.email && String(rec.email).toLowerCase() === emLc) {
          matched = { userId: uid, rec: rec };
        }
      });
      if (matched) {
        return '<span style="display:inline-flex;align-items:center;gap:3px;background:#dcfce7;color:#166534;padding:1px 6px;border-radius:3px;font-size:10px;font-weight:600;margin:1px;" title="' + _esc(em) + '">' +
          _esc(_displayName(matched.userId)) +
        '</span>';
      }
      return '<span style="display:inline-flex;align-items:center;background:#f1f5f9;color:#475569;padding:1px 6px;border-radius:3px;font-size:10px;font-family:Monaco,monospace;margin:1px;" title="No identity record">' +
        _esc(em) +
      '</span>';
    }
    function _summaryUserIdChip(uid) {
      if (!uid) return '';
      var rec = _lookup && _lookup[uid];
      if (rec) {
        return '<span style="display:inline-flex;align-items:center;gap:3px;background:#ede9fe;color:#5b21b6;padding:1px 6px;border-radius:3px;font-size:10px;font-weight:600;margin:1px;" title="' + _esc(uid) + '">' +
          _esc(_displayName(uid)) +
        '</span>';
      }
      return '<span style="display:inline-flex;align-items:center;background:#f1f5f9;color:#475569;padding:1px 6px;border-radius:3px;font-size:10px;font-family:Monaco,monospace;margin:1px;" title="No identity record">' +
        _esc(uid) +
      '</span>';
    }
    function _summaryDomainChip(d) {
      return '<span style="display:inline-flex;align-items:center;background:#cffafe;color:#155e75;padding:1px 6px;border-radius:3px;font-size:10px;font-family:Monaco,monospace;font-weight:600;margin:1px;">' +
        _esc(d) +
      '</span>';
    }
    function _excChip(emEx, uidEx) {
      var bits = [];
      if (emEx && emEx.length) bits.push(emEx.length + ' email exc');
      if (uidEx && uidEx.length) bits.push(uidEx.length + ' UUID exc');
      if (!bits.length) return '';
      return ' <span style="font-size:9px;color:#b91c1c;background:#fee2e2;padding:1px 5px;border-radius:3px;font-weight:700;" title="Has audience excludes — see below">⚠ ' + bits.join(', ') + '</span>';
    }
    function _renderCategorySection(icon, label, items, builder, openByDefault) {
      if (!items.length) return '';
      return '<details class="_eli3_af_aud_cat"' + (openByDefault ? ' open' : '') + '>' +
        '<summary class="_eli3_af_aud_cat_header">' +
          icon + ' ' + label + ' (' + items.length + ')' +
        '</summary>' +
        '<div class="_eli3_af_aud_cat_body">' + items.map(builder).join('') + '</div>' +
      '</details>';
    }
    var audienceBodyHtml = '';
    audienceBodyHtml += _renderCategorySection('🌍', 'Public', categories.public, function (t) {
      var chips = '<span style="color:#15803d;font-size:11px;">audience: ["all"]</span>';
      if (t.excludes.length) chips += _excChip(t.entry.audienceEmailExcludes, t.entry.audienceUserIdExcludes);
      return _toolRow(t.id, chips);
    }, false);
    audienceBodyHtml += _renderCategorySection('📧', 'Email-restricted', categories.emails, function (t) {
      var summaryChips = t.emails.map(_summaryEmailChip).join('');
      var body = '<div style="display:flex;flex-direction:column;gap:4px;">' +
        t.emails.map(function (em) {
          return '<div>' + _resolveEmailChip(em) + '</div>';
        }).join('') +
      '</div>' + _excChip(t.entry.audienceEmailExcludes, t.entry.audienceUserIdExcludes);
      return _toolRow(t.id, body, summaryChips);
    }, true);
    audienceBodyHtml += _renderCategorySection('🆔', 'UUID-restricted', categories.userIds, function (t) {
      var summaryChips = t.userIds.map(_summaryUserIdChip).join('');
      var body = '<div style="display:flex;flex-direction:column;gap:4px;">' +
        t.userIds.map(function (uid) { return '<div>' + _resolveUserIdChip(uid) + '</div>'; }).join('') +
      '</div>' + _excChip(t.entry.audienceEmailExcludes, t.entry.audienceUserIdExcludes);
      return _toolRow(t.id, body, summaryChips);
    }, true);
    audienceBodyHtml += _renderCategorySection('🌐', 'Domain-restricted', categories.domains, function (t) {
      var summaryChips = t.domains.map(_summaryDomainChip).join('');
      var body = '<div style="display:flex;flex-direction:column;gap:4px;">' +
        t.domains.map(function (d) {
          return '<div><code style="font:10.5px/1.2 Monaco,monospace;color:#0f172a;">' + _esc(d) + '</code></div>';
        }).join('') +
      '</div>' + _excChip(t.entry.audienceEmailExcludes, t.entry.audienceUserIdExcludes);
      return _toolRow(t.id, body, summaryChips);
    }, false);
    audienceBodyHtml += _renderCategorySection('🏷', 'Tag/group-restricted', categories.tags, function (t) {
      var body = '<div style="display:flex;flex-wrap:wrap;gap:4px;">' +
        t.tags.map(function (tag) {
          return '<span style="font-size:10px;background:#e0e7ff;color:#3730a3;padding:1px 6px;border-radius:3px;">' + _esc(tag) + '</span>';
        }).join('') +
      '</div>' + _excChip(t.entry.audienceEmailExcludes, t.entry.audienceUserIdExcludes);
      return _toolRow(t.id, body);
    }, false);
    audienceBodyHtml += _renderCategorySection('🚫', 'With excludes', categories.excluded, function (t) {
      var body = '<div style="display:flex;flex-direction:column;gap:4px;">';
      (t.emailExcludes || []).forEach(function (em) {
        body += '<div>📧 ' + _resolveEmailChip(em) + '</div>';
      });
      (t.userIdExcludes || []).forEach(function (uid) {
        body += '<div>🆔 ' + _resolveUserIdChip(uid) + '</div>';
      });
      body += '</div>';
      return _toolRow(t.id, body);
    }, false);
    audienceBodyHtml += _renderCategorySection('⚠️', 'Open / no audience (defaults public)', categories.open, function (t) {
      var body = '<div style="display:flex;align-items:center;justify-content:space-between;gap:8px;flex-wrap:wrap;">' +
        '<span style="color:#92400e;font-size:11px;flex:1;min-width:200px;">No audience fields declared — behaves as public broadcast. Set an audience explicitly if this isn\'t intended.</span>' +
        '<button class="_eli3_af_btn_mini" data-act="tool-make-public" data-tool="' + _esc(t.id) + '" title="Set audience: [\'all\'] on the manifest entry — makes the implicit-public state explicit (single commit).">→ Make Public</button>' +
      '</div>';
      return _toolRow(t.id, body);
    }, false);
    var audienceHtml = '';
    if (catTotal) {
      audienceHtml = '<div class="_eli3_af_section">' +
        '<details class="_eli3_af_audit">' +
          '<summary class="_eli3_af_section_header">🎯 Tool Audience — ' +
            catTotal + ' tool' + (catTotal === 1 ? '' : 's') +
            ' · <span style="color:#15803d;">' + catTotals.public + ' public</span>' +
            (catTotals.emails ? ' · <span style="color:#1565c0;">' + catTotals.emails + ' email</span>' : '') +
            (catTotals.userIds ? ' · <span style="color:#7c3aed;">' + catTotals.userIds + ' UUID</span>' : '') +
            (catTotals.domains ? ' · <span style="color:#0891b2;">' + catTotals.domains + ' domain</span>' : '') +
            (catTotals.tags ? ' · <span style="color:#3730a3;">' + catTotals.tags + ' tag</span>' : '') +
            (catTotals.excluded ? ' · <span style="color:#b91c1c;">' + catTotals.excluded + ' w/ excludes</span>' : '') +
            (catTotals.open ? ' · <span style="color:#92400e;">' + catTotals.open + ' open</span>' : '') +
            ' (click to expand)' +
          '</summary>' +
          '<div class="_eli3_af_audit_body">' + audienceBodyHtml + '</div>' +
        '</details>' +
      '</div>';
    }

    // 2026-05-25: Data Libraries section — lists all kind=data manifest
    // entries with force-redownload + delete buttons. Reads from the
    // already-cached _toolsManifest (loaded at boot). Both actions push
    // overrides via the same _pushOverride pipeline as tools/settings/etc.
    var librariesHtml = "";
    if (_toolsManifest && Array.isArray(_toolsManifest.tools)) {
      var dataLibs = _toolsManifest.tools.filter(function (t) {
        return t && t.kind === "data";
      });
      if (dataLibs.length) {
        var libRows = dataLibs.map(function (lib) {
          // Strip the __data_ prefix for the action payload — the kernel's
          // uninstallData(id) takes the bare id and re-derives the store.
          var bareId = String(lib.id || "").replace(/^__data_/, "");
          var label = lib.label || bareId;
          return (
            '<div class="_eli3_af_tool_row" style="display:flex;align-items:center;gap:10px;padding:8px 12px;border-bottom:1px solid #f1f5f9;">' +
              '<span style="font-size:14px;width:22px;text-align:center;">📦</span>' +
              '<div style="flex:1;min-width:0;">' +
                '<div style="font:600 13px/1.2 Inter,sans-serif;color:#0f172a;">' + _esc(label) + '</div>' +
                '<div style="font-size:11px;color:#64748b;margin-top:2px;">' +
                  '<code style="font-size:10px;background:#f1f5f9;padding:1px 4px;border-radius:2px;">' + _esc(bareId) + '</code>' +
                  ' · v' + _esc(lib.version || "?") +
                  (lib.size ? ' · ' + Math.round(lib.size / 1024) + ' KB' : "") +
                '</div>' +
              '</div>' +
              '<button class="_eli3_af_btn" data-act="lib-redownload" data-lib-id="' + _esc(bareId) + '" data-lib-label="' + _esc(label) + '" title="Force every recipient to re-fetch this library from CDN on next manifest poll. Existing rows are preserved during the gap.">🔄 Redownload</button>' +
              '<button class="_eli3_af_btn _eli3_af_btn_danger" data-act="lib-delete" data-lib-id="' + _esc(bareId) + '" data-lib-label="' + _esc(label) + '" title="Wipe rows + stamps from every recipient. Will reinstall on next manifest poll unless audience also changes.">🗑 Delete</button>' +
            '</div>'
          );
        }).join("");
        librariesHtml =
          '<div class="_eli3_af_section">' +
            '<details class="_eli3_af_audit">' +
              '<summary class="_eli3_af_section_header">📦 Data Libraries — ' +
                dataLibs.length + ' libraries (click to expand)' +
              '</summary>' +
              '<div class="_eli3_af_audit_body">' +
                '<div style="padding:8px 12px;background:#f1f5f9;font-size:11.5px;color:#475569;border-radius:5px;margin-bottom:8px;">' +
                  'Force-redownload preserves existing rows during the gap (library stays functional). ' +
                  'Delete wipes rows + clears stamps (library disappears until next manifest poll). ' +
                  'Both push to <b>everyone with the library installed</b> — narrow scope by editing audience in the override JSON.' +
                '</div>' +
                libRows +
              '</div>' +
            '</details>' +
          '</div>';
      }
    }

    out.innerHTML =
      '<div class="_eli3_af_root">' +
        headerHtml +
        // 2026-05-23 (Phase 2): audit pivot above the per-user cards so
        // it's visible without scrolling, but collapsed by default to
        // keep the focus on the user cards (which are the primary view).
        auditHtml +
        audienceHtml +
        librariesHtml +
        // 2026-05-23: resolved (identified) users first, unresolved below.
        // Reduces clutter for admins who mostly look at known fleet.
        resolvedHtml +
        unresolvedHtml +
      '</div>';

    // Wire actions
    document.getElementById("_af_refresh").onclick = function () { _launch(true); };
    document.getElementById("_af_broadcast").onclick = function () { _showNoticePusher(null); };
    var pushSurveyBtn = document.getElementById("_af_push_survey");
    if (pushSurveyBtn) pushSurveyBtn.onclick = function () { _showSurveyPusher(null); };
    var pushLayoutBtn = document.getElementById("_af_push_layout");
    if (pushLayoutBtn) pushLayoutBtn.onclick = function () { _showDashboardLayoutPusher(null); };
    // 2026-05-25: AI Models Manager — comprehensive admin UI for
    // managing ai_model_list + ai_model + ai_image_model. Replaces the
    // previous standalone Discover button (which is now a sub-flow
    // inside this manager). IDB-backed working draft.
    var mgrBtn = document.getElementById("_af_ai_models_mgr");
    if (mgrBtn) {
      mgrBtn.onclick = function () {
        if (typeof window.showAiModelsManager === "function") {
          try { window.showAiModelsManager(); }
          catch (e) {
            if (typeof showToast === "function") showToast("AI Models Manager failed: " + (e && e.message), "err");
          }
        } else if (typeof showToast === "function") {
          showToast("AI Models Manager module not loaded.", "warn");
        }
      };
    }
    document.getElementById("_af_close").onclick = function () {
      if (eli.dashboard && eli.dashboard.goHome) eli.dashboard.goHome();
    };
    // 2026-05-23 bug fix: use .onclick assignment (replaces) instead of
    // addEventListener (stacks). _renderDashboard() runs after every save /
    // push / refresh; with addEventListener each re-render added a NEW
    // handler, so a single click opened N stacked dialogs (one per render
    // since boot). User saw "click Cancel 2-3 times to dismiss" + backdrop
    // dimming visibly getting lighter as each overlay peeled away.
    out.onclick = function (ev) {
      var t = ev.target;
      while (t && t !== out) {
        var act = t.getAttribute && t.getAttribute("data-act");
        if (act) {
          // 2026-05-23 (Phase 2): close any open per-tool dropdown after
          // clicking an action inside it — without this the panel stays
          // open after the action fires (since <details> only toggles on
          // summary click). Walk up to find a containing _eli3_af_tool_menu
          // details element and close it via removeAttribute("open").
          var menuWalker = t;
          while (menuWalker && menuWalker !== out) {
            if (menuWalker.classList && menuWalker.classList.contains("_eli3_af_tool_menu")) {
              try { menuWalker.removeAttribute("open"); } catch (_e) {}
              break;
            }
            menuWalker = menuWalker.parentNode;
          }
          var uid = t.getAttribute("data-uid");
          if (act === "add-identity") return _showIdentityEditor(uid, true);
          if (act === "edit-identity") return _showIdentityEditor(uid, false);
          if (act === "delete-user") return _showDeleteUserConfirm(uid);
          if (act === "link-to-identity") return _linkUserToIdentity(uid, t.getAttribute("data-old-uid"));
          if (act === "push-setting") return _showSettingPusher(uid);
          if (act === "push-setting-key") return _showSettingPusher(uid, t.getAttribute("data-key"));
          if (act === "send-notice") return _showNoticePusher(uid);
          if (act === "push-survey") return _showSurveyPusher(uid);
          if (act === "push-layout") return _showDashboardLayoutPusher(uid);
          if (act === "lib-redownload") return _showDataLibraryPusher(t.getAttribute("data-lib-id"), "redownload", t.getAttribute("data-lib-label"));
          if (act === "lib-delete") return _showDataLibraryPusher(t.getAttribute("data-lib-id"), "delete", t.getAttribute("data-lib-label"));
          if (act === "tool-disable") return _showToolPusher(uid, t.getAttribute("data-tool"), "disable_tool");
          if (act === "tool-enable") return _showToolPusher(uid, t.getAttribute("data-tool"), "enable_tool");
          if (act === "tool-redownload") return _showToolPusher(uid, t.getAttribute("data-tool"), "force_redownload_tool");
          if (act === "tool-uninstall") return _showToolUninstaller(uid, t.getAttribute("data-tool"));
          if (act === "tool-regrant") return _showToolRegrant(uid, t.getAttribute("data-tool"));
          if (act === "tool-pin") return _pushPinAction(uid, t.getAttribute("data-tool"), true);
          if (act === "tool-unpin") return _pushPinAction(uid, t.getAttribute("data-tool"), false);
          // 2026-05-23 (Phase 2): override-based Grant/Revoke/Clear.
          // Single override push to admin-overrides.json — no manifest
          // mutation, no GitHub commit. Inverse of tool-uninstall (which
          // rewrites manifest audience).
          if (act === "tool-grant") return _pushAudienceOverride(uid, t.getAttribute("data-tool"), "audience_grant_user");
          if (act === "tool-revoke") return _pushAudienceOverride(uid, t.getAttribute("data-tool"), "audience_revoke_user");
          if (act === "tool-clear-override") return _pushAudienceOverride(uid, t.getAttribute("data-tool"), "audience_clear_user_override");
          if (act === "tool-grant-picker") return _showGrantPicker(uid);
          // 2026-05-23 (Phase 2): audit panel's per-row Clear button.
          // Identical to tool-clear-override but reads uid from the audit
          // row rather than the parent user card (the audit's rows aren't
          // inside a user card scope).
          if (act === "audit-clear") return _pushAudienceOverride(uid, t.getAttribute("data-tool"), "audience_clear_user_override");
          // 2026-05-23 (Phase 2): open audience editor for a tool from
          // the Tool Audience Browser. Mutates the manifest entry directly.
          if (act === "tool-edit-audience") return _showAudienceEditor(t.getAttribute("data-tool"));
          // 2026-05-23 (Phase 2): bulk push for an entire tool — single
          // override targets all users (or a comma-separated list).
          if (act === "tool-bulk-revoke") return _showBulkAudiencePusher(t.getAttribute("data-tool"), "revoke");
          if (act === "tool-bulk-uninstall") return _showBulkAudiencePusher(t.getAttribute("data-tool"), "uninstall");
          if (act === "tool-make-public") return _makeToolPublic(t.getAttribute("data-tool"));
          if (act === "remove-override") {
            var oid = t.getAttribute("data-oid");
            if (!oid) return;
            _toast("⏳ Removing override…", "info");
            _removeOverride(oid).then(function (ok) {
              if (ok) _toast("✅ Override removed", "ok");
              _renderDashboard();
            }).catch(function (err) { _toast("Remove failed: " + err.message, "err"); });
            return;
          }
          if (act === "revert-override") {
            var roid = t.getAttribute("data-oid");
            if (!roid) return;
            return _revertOverride(roid);
          }
        }
        t = t.parentNode;
      }
    };
  }

  function _launch(force) {
    // 2026-05-25: self-record launch — kernel only records tile.id, but
    // eli_telemetry's etDeriveToolName only buckets "appOpened*" names.
    try { if (eli.stats && eli.stats.record) eli.stats.record("appOpenedAdminFleet"); } catch (_) {}
    _toast("⏳ Loading fleet data…", "info");
    return _bootstrap().then(function () {
      _renderDashboard();
      eli.log.event("tool", "admin_fleet_loaded", {
        users: _allUsers().length,
        unresolved: _unresolvedUsers().length,
        overrides: (_adminOverrides && _adminOverrides.overrides || []).length,
      });
    }).catch(function (err) {
      _toast("Fleet load failed: " + (err.message || "unknown"), "err");
      eli.log.event("tool", "admin_fleet_load_failed", { msg: err && err.message });
      // Render a fallback message
      var out = window.eli.ui.claimOutput();
      out.innerHTML =
        '<div class="_eli3_af_root">' +
          '<div class="_eli3_af_error">' +
            '<h2>👥 ELI Fleet — Setup needed</h2>' +
            '<p>' + _esc(err.message || "Unknown error") + '</p>' +
            '<p>Make sure both <code>eli_user_github_pat</code> and <code>eli_admin_password</code> are set ' +
              '(usually via importing a credentials bundle in Admin Library Publisher).</p>' +
            '<button class="_eli3_af_btn" id="_af_retry">🔄 Retry</button>' +
          '</div>' +
        '</div>';
      document.getElementById("_af_retry").onclick = function () { _launch(); };
    });
  }

  // ── Tile registration ────────────────────────────────────────────
  if (eli.register) {
    eli.register({
      tile: {
        app_admin_fleet: eli.events.guard ? eli.events.guard(function () { _launch(); }, "admin_fleet.tile") : function () { _launch(); },
      },
    });
  }

  eli.log.event("tool", "admin_fleet_initialized", {});
}

jsonTools.css:
/* admin_fleet — fleet dashboard styling
   Light palette in both themes (per CLAUDE.md tools+dialogs rule). */

._eli3_af_root {
  font: 13px/1.4 'Inter', system-ui, sans-serif;
  color: #0f172a;
  background: #f8fafc;
  padding: 16px;
  min-height: 100vh;
  box-sizing: border-box;
  /* 2026-05-23: kernel's .output-area is a flex column with transparent
     bg — without flex grow, tool sizes to content and scroll exposes the
     body's navy dashboard bg below. */
  flex: 1 0 auto;
}
.beta-ui-active .output-area:has(> ._eli3_af_root),
.output-area:has(> ._eli3_af_root) {
  background: #f8fafc !important;
}

._eli3_af_header {
  display: flex;
  align-items: center;
  gap: 16px;
  padding: 12px 16px;
  background: linear-gradient(135deg, #1e3a8a 0%, #1565c0 100%);
  color: #fff;
  border-radius: 0;
  margin-bottom: 14px;
}
._eli3_af_header_title {
  font-family: 'Georgia', serif;
  font-size: 18px;
  font-weight: 700;
  display: flex;
  align-items: center;
  gap: 8px;
}
._eli3_af_header_icon { font-size: 20px; }
._eli3_af_header_meta {
  font-size: 11px;
  color: #cbd5e1;
  letter-spacing: 0.5px;
  flex: 1;
}
._eli3_af_header_actions {
  display: flex;
  gap: 6px;
}
._eli3_af_header_actions ._eli3_af_btn {
  background: rgba(255,255,255,0.15);
  border-color: rgba(255,255,255,0.3);
  color: #fff;
}
._eli3_af_header_actions ._eli3_af_btn:hover {
  background: rgba(255,255,255,0.25);
}

._eli3_af_section {
  margin-bottom: 16px;
}
._eli3_af_section_header {
  font: 700 10px/1 'Inter', sans-serif;
  text-transform: uppercase;
  letter-spacing: 1px;
  color: #475569;
  padding: 8px 4px;
  border-bottom: 1px solid #cbd5e1;
  margin-bottom: 8px;
}
._eli3_af_empty {
  padding: 24px 12px;
  text-align: center;
  color: #94a3b8;
  font-size: 12px;
}

._eli3_af_card {
  background: #fff;
  border: 1px solid #e2e8f0;
  border-left: 4px solid #1565c0;
  padding: 12px 14px;
  margin-bottom: 8px;
}
._eli3_af_card[data-uid] ._eli3_af_card_header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  margin-bottom: 4px;
}
._eli3_af_card_name {
  font: 700 14px/1.2 'Inter', sans-serif;
  color: #0f172a;
}
._eli3_af_card_badges {
  display: flex;
  gap: 4px;
  flex-shrink: 0;
}
._eli3_af_badge {
  font: 700 9px/1 'Inter', sans-serif;
  text-transform: uppercase;
  letter-spacing: 0.5px;
  padding: 3px 6px;
  border-radius: 2px;
}
._eli3_af_badge_role {
  background: #e0e7ff; color: #3730a3; border: 1px solid #c7d2fe;
}
._eli3_af_badge_active {
  background: #dcfce7; color: #14532d; border: 1px solid #86efac;
}
._eli3_af_badge_trial {
  background: #fef3c7; color: #92400e; border: 1px solid #fde68a;
}
._eli3_af_badge_offboarded {
  background: #f1f5f9; color: #64748b; border: 1px solid #cbd5e1;
}
._eli3_af_badge_legacy {
  background: #fde68a; color: #78350f; border: 1px solid #fbbf24;
}

._eli3_af_card_meta {
  font: 500 10.5px/1.4 'Inter', sans-serif;
  color: #64748b;
  margin-bottom: 8px;
  display: flex;
  flex-wrap: wrap;
  gap: 0;
}
._eli3_af_card_meta span { white-space: nowrap; }

._eli3_af_card_actions {
  display: flex;
  gap: 6px;
  margin: 6px 0;
  flex-wrap: wrap;
}

._eli3_af_btn {
  font: 600 11px/1 'Inter', sans-serif;
  padding: 6px 10px;
  background: linear-gradient(180deg, #f8fafc 0%, #e2e8f0 100%);
  border: 1px solid #cbd5e1;
  border-bottom-width: 2px;
  color: #0f172a;
  cursor: pointer;
  border-radius: 3px;
  transition: filter 0.12s;
}
._eli3_af_btn:hover { filter: brightness(0.97); }
._eli3_af_btn_primary {
  background: linear-gradient(180deg, #1565c0 0%, #0d47a1 100%);
  border-color: #0d47a1;
  color: #fff;
}
._eli3_af_btn_primary:hover { filter: brightness(1.08); }

._eli3_af_btn_mini {
  font: 600 10px/1 'Inter', sans-serif;
  padding: 3px 6px;
  background: linear-gradient(180deg, #f8fafc 0%, #e2e8f0 100%);
  border: 1px solid #cbd5e1;
  color: #0f172a;
  cursor: pointer;
  border-radius: 2px;
  transition: filter 0.12s;
}
._eli3_af_btn_mini:hover { filter: brightness(0.95); }
._eli3_af_btn_danger {
  background: linear-gradient(180deg, #fef2f2 0%, #fee2e2 100%);
  border-color: #fca5a5;
  color: #991b1b;
}
._eli3_af_btn_warn {
  background: linear-gradient(180deg, #fffbeb 0%, #fef3c7 100%);
  border-color: #fcd34d;
  color: #92400e;
}

._eli3_af_tool_menu {
  position: relative;
  display: inline-block;
}
._eli3_af_tool_menu > summary {
  list-style: none;
  cursor: pointer;
  padding: 3px 8px;
  font-weight: 700;
  line-height: 1;
}
._eli3_af_tool_menu > summary::-webkit-details-marker { display: none; }
._eli3_af_tool_menu > summary::marker { content: ""; }
._eli3_af_tool_menu[open] > summary {
  background: linear-gradient(180deg, #f1f5f9 0%, #e2e8f0 100%);
  border-color: #94a3b8;
}
._eli3_af_menu_panel {
  position: absolute;
  right: 0;
  top: 100%;
  margin-top: 4px;
  z-index: 50;
  background: white;
  border: 1px solid #cbd5e1;
  border-radius: 6px;
  box-shadow: 0 6px 18px rgba(15, 23, 42, 0.18);
  display: flex;
  flex-direction: column;
  min-width: 180px;
  padding: 4px;
}
._eli3_af_menu_item {
  display: block;
  width: 100%;
  text-align: left;
  padding: 6px 10px;
  font-size: 11px;
  font-weight: 600;
  color: #334155;
  background: transparent;
  border: 0;
  border-radius: 4px;
  cursor: pointer;
  white-space: nowrap;
}
._eli3_af_menu_item:hover { background: #f1f5f9; }
._eli3_af_menu_item_warn { color: #92400e; }
._eli3_af_menu_item_warn:hover { background: #fef3c7; }
._eli3_af_menu_item_danger { color: #991b1b; }
._eli3_af_menu_item_danger:hover { background: #fee2e2; }

._eli3_af_audit > summary {
  cursor: pointer;
  user-select: none;
}
._eli3_af_audit_body {
  padding: 8px 12px;
  background: #f8fafc;
  border-radius: 6px;
  margin-top: 6px;
}
._eli3_af_audit_tool {
  margin-bottom: 6px;
  background: white;
  border: 1px solid #e2e8f0;
  border-radius: 5px;
}
._eli3_af_audit_tool > summary {
  cursor: pointer;
  user-select: none;
  padding: 6px 10px;
  font-size: 12px;
}
._eli3_af_audit_tool_header code {
  font-family: Monaco, monospace;
  font-size: 11px;
  background: #f1f5f9;
  padding: 1px 6px;
  border-radius: 3px;
  color: #0f172a;
}
._eli3_af_audit_users {
  padding: 4px 12px 8px;
  display: flex;
  flex-direction: column;
  gap: 4px;
}
._eli3_af_audit_user_row {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 11px;
  color: #334155;
  padding: 3px 0;
  border-top: 1px dashed #f1f5f9;
}
._eli3_af_audit_user_row:first-child { border-top: 0; }
._eli3_af_audit_user_name {
  flex: 1;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

._eli3_af_aud_cat {
  margin-bottom: 6px;
  background: #fafbfc;
  border: 1px solid #e2e8f0;
  border-radius: 5px;
}
._eli3_af_aud_cat > summary {
  cursor: pointer;
  user-select: none;
  padding: 6px 10px;
  font-size: 12px;
  font-weight: 700;
  color: #334155;
}
._eli3_af_aud_cat_body {
  padding: 4px 12px 8px;
  display: flex;
  flex-direction: column;
  gap: 4px;
}
._eli3_af_aud_tool {
  background: white;
  border: 1px solid #e2e8f0;
  border-radius: 4px;
}
._eli3_af_aud_tool > summary {
  cursor: pointer;
  user-select: none;
  padding: 5px 10px;
  font-size: 11px;
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 8px;
}
._eli3_af_aud_tool_summary_main {
  flex: 1;
  min-width: 0;
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 4px 6px;
  line-height: 1.6;
}
._eli3_af_aud_tool_header code {
  font-family: Monaco, monospace;
  font-size: 11px;
  background: #f1f5f9;
  padding: 1px 6px;
  border-radius: 3px;
  color: #0f172a;
}
._eli3_af_aud_tool_body {
  padding: 6px 12px 8px;
  border-top: 1px dashed #f1f5f9;
  font-size: 11px;
}

._eli3_af_settings,
._eli3_af_tools,
._eli3_af_overrides {
  margin-top: 8px;
  padding-top: 8px;
  border-top: 1px dashed #e2e8f0;
  font-size: 11px;
}
._eli3_af_settings_header,
._eli3_af_tools_header,
._eli3_af_overrides_header {
  font: 700 9px/1 'Inter', sans-serif;
  text-transform: uppercase;
  letter-spacing: 1px;
  color: #475569;
  margin-bottom: 4px;
}
/* 2026-05-23c: collapsible-section styling for <details>/<summary>. */
summary._eli3_af_settings_header,
summary._eli3_af_tools_header {
  cursor: pointer;
  padding: 4px 6px;
  margin-bottom: 0;
  background: #f8fafc;
  border: 1px solid #e2e8f0;
  border-radius: 3px;
  user-select: none;
  list-style: revert;
}
summary._eli3_af_settings_header:hover,
summary._eli3_af_tools_header:hover {
  background: #f1f5f9;
}
details[open] > summary._eli3_af_settings_header,
details[open] > summary._eli3_af_tools_header {
  margin-bottom: 6px;
}
/* 2026-05-23c+: status chips on active admin pushes. */
._eli3_af_chip {
  display: inline-block;
  font: 700 9px/1 'Inter', sans-serif;
  text-transform: uppercase;
  letter-spacing: 0.5px;
  padding: 3px 6px;
  border-radius: 10px;
  border: 1px solid;
  white-space: nowrap;
}
._eli3_af_chip_ok {
  background: #dcfce7;
  color: #14532d;
  border-color: #86efac;
}
._eli3_af_chip_pending {
  background: #fef3c7;
  color: #92400e;
  border-color: #fde68a;
}
/* Legacy/warning callout used by the encrypted-push and setting dialogs. */
._eli3_af_warn {
  padding: 8px 10px;
  background: #fef3c7;
  border: 1px solid #fde68a;
  border-left: 3px solid #f59e0b;
  border-radius: 3px;
  font-size: 11px;
  color: #92400e;
  margin-bottom: 6px;
}
._eli3_af_settings_list,
._eli3_af_tools_list {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 2px 12px;
}
._eli3_af_settings_row,
._eli3_af_tools_row {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: 10.5px;
  color: #475569;
  padding: 1px 0;
}
._eli3_af_settings_key { font-weight: 700; color: #0f172a; }
._eli3_af_settings_val { color: #1565c0; }
._eli3_af_tools_id { flex: 1; color: #0f172a; }
._eli3_af_tools_disabled { color: #b91c1c; font-weight: 700; font-size: 9px; }
._eli3_af_tools_actions { display: flex; gap: 2px; }

._eli3_af_overrides_row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 6px;
  padding: 3px 6px;
  background: #fef3c7;
  border: 1px solid #fde68a;
  margin-bottom: 3px;
  font-size: 10.5px;
  color: #92400e;
}

/* Installed-tools line — at-a-glance list of tool IDs in card meta */
._eli3_af_installed_line {
  margin: 4px 0 4px 0;
  padding: 6px 8px;
  background: #f8fafc;
  border-left: 3px solid #1565c0;
  font: 500 11px/1.5 'Inter', sans-serif;
  color: #475569;
  word-break: break-all;
}
._eli3_af_installed_line_legacy {
  border-left-color: #fbbf24;
}
._eli3_af_installed_label {
  font: 700 9.5px/1 'Inter', sans-serif;
  text-transform: uppercase;
  letter-spacing: 0.5px;
  color: #0f172a;
  margin-right: 4px;
}

/* Excluded-tools section — tools where user is in audienceEmailExcludes */
._eli3_af_excluded {
  margin-top: 8px;
  padding-top: 8px;
  border-top: 1px dashed #e2e8f0;
}
._eli3_af_excluded_header {
  font: 700 9px/1 'Inter', sans-serif;
  text-transform: uppercase;
  letter-spacing: 1px;
  color: #b91c1c;
  margin-bottom: 4px;
}
._eli3_af_excluded_row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 6px;
  padding: 3px 6px;
  background: #fef2f2;
  border: 1px solid #fecaca;
  margin-bottom: 3px;
  font-size: 10.5px;
  color: #991b1b;
}
._eli3_af_excluded_id { flex: 1; font-weight: 600; }

._eli3_af_form {
  display: flex;
  flex-direction: column;
  gap: 10px;
}
._eli3_af_form_row {
  display: grid;
  grid-template-columns: 120px 1fr;
  gap: 10px;
  align-items: center;
}
._eli3_af_form_row label {
  font: 700 11px/1.2 'Inter', sans-serif;
  color: #475569;
  text-transform: uppercase;
  letter-spacing: 0.4px;
}
._eli3_af_form_row input,
._eli3_af_form_row select,
._eli3_af_form_row textarea {
  font: 500 12px/1.3 'Inter', sans-serif;
  padding: 6px 8px;
  border: 1px solid #cbd5e1;
  border-radius: 2px;
  background: #fff;
  color: #0f172a;
  outline: none;
  width: 100%;
  box-sizing: border-box;
}
._eli3_af_form_row input:focus,
._eli3_af_form_row select:focus,
._eli3_af_form_row textarea:focus {
  border-color: #1565c0;
}
._eli3_af_form_val_static {
  font: 500 11.5px/1.3 'Inter', sans-serif;
  color: #475569;
  padding: 4px 0;
}
._eli3_af_req { color: #b91c1c; }
._eli3_af_radio {
  display: inline-block;
  padding: 2px 0;
  font-size: 11px;
}

._eli3_af_error {
  background: #fff;
  border: 1px solid #fca5a5;
  border-left: 4px solid #b91c1c;
  padding: 16px;
  border-radius: 0;
}
._eli3_af_error h2 {
  margin: 0 0 8px 0;
  font: 700 16px/1.2 'Georgia', serif;
  color: #991b1b;
}
._eli3_af_error p {
  margin: 6px 0;
  font-size: 12px;
  color: #475569;
}
._eli3_af_error code {
  background: #f1f5f9;
  padding: 1px 6px;
  border-radius: 2px;
  font-family: 'Monaco', monospace;
  font-size: 11px;
}
